import asyncio
from typing import List, Callable, Dict, Any

async def monitor_tasks(coroutines: List[Callable]) -> Dict[str, Any]:
    tasks = {}
    for i, coro in enumerate(coroutines):
        task_name = f"task_{i}"
        task = asyncio.Task(coro(), name=task_name)
        tasks[task_name] = task

    results = {}
    for task_name, task in tasks.items():
        try:
            result = await task
            results[task_name] = result
        except Exception as e:
            results[task_name] = e

    return results

import asyncio

def create_semaphores(concurrent_limits, loop=None):
    if loop is not None:
        import warnings
        warnings.warn(
            "The 'loop' argument is deprecated and will be ignored.",
            DeprecationWarning,
            stacklevel=2
        )
    return [asyncio.Semaphore(limit) for limit in concurrent_limits]

