import asyncio

def safe_cancel(coro):
    async def wrapper():
        try:
            return await coro
        except asyncio.CancelledError:
            return 'Cancelled gracefully'
    return asyncio.run(wrapper())

import asyncio
import time

async def measure_sleep_timing() -> tuple[float, float]:
    start = time.perf_counter()
    for _ in range(100):
        await asyncio.sleep(0.001)
    end = time.perf_counter()
    total_elapsed = end - start
    average_sleep = total_elapsed / 100
    return (total_elapsed, average_sleep)

