import json
from collections import UserString


class ConfigString(UserString):
    def __init__(self, data):
        super().__init__(data)
        try:
            self._config_dict = json.loads(data)
        except json.JSONDecodeError:
            self._config_dict = {}

    def __or__(self, other):
        if not isinstance(other, ConfigString):
            return NotImplemented
        merged_dict = {**self._config_dict, **other._config_dict}
        return ConfigString(json.dumps(merged_dict))


def merge_config_strings(base_config: str, override_config: str) -> str:
    base = ConfigString(base_config)
    override = ConfigString(override_config)
    merged = base | override
    return merged.data

