def validate_and_log_urls(urls: List[str]) -> Dict[str, Union[str, Exception]]:
    results = {}

    for url in urls:
        try:
            parsed = urlparse(url)

            if not parsed.scheme or not parsed.netloc:
                results[url] = InvalidURL(f"Invalid URL structure: {url}")
                continue

            requests.utils.requote_uri(url)

