import importlib.resources
from importlib.abc import Traversable
from typing import List


def list_package_resources(package_name: str, resource_dir: str = "") -> List[str]:
    package = importlib.import_module(package_name)
    base_path: Traversable = importlib.resources.files(package)

    if resource_dir:
        target_path = base_path.joinpath(resource_dir)
    else:
        target_path = base_path

    if not target_path.is_dir():
        return []

    result = []

    def traverse(current: Traversable, prefix: str = "") -> None:
        for item in current.iterdir():
            item_name = item.name
            full_path = f"{prefix}/{item_name}" if prefix else item_name

            if item.is_file():
                result.append(full_path)
            elif item.is_dir():
                traverse(item, full_path)

    traverse(target_path, "")
    return result

