def extract_constants(node: ast.AST, version: tuple[int, int]) -> List[ast.Constant]:
    constants = []

    def visit(node: ast.AST) -> None:
        if isinstance(node, ast.Constant):
            constants.append(node)
        elif version < (3, 8):
            if isinstance(node, ast.NameConstant):
                constants.append(ast.Constant(value=node.value))
            elif isinstance(node, ast.Num):
                constants.append(ast.Constant(value=node.n))
            elif isinstance(node, ast.Str):
                constants.append(ast.Constant(value=node.s))
            elif isinstance(node, ast.Bytes):
                constants.append(ast.Constant(value=node.s))
            elif isinstance(node, ast.Ellipsis):
                constants.append(ast.Constant(value=...))
        for child in ast.iter_child_nodes(node):
            visit(child)

    visit(node)
    return constants

