from pydantic import validate_email

def process_user_import(user_list: List[Tuple[str, str]]) -> Dict[str, List]:
    if not isinstance(user_list, list):
        raise TypeError("user_list must be a list of tuples")

    valid_users = []
    rejected_entries = []

    for idx, (name, email) in enumerate(user_list):
        if not isinstance(name, str) or not isinstance(email, str):
            rejected_entries.append({
                'index': idx,
                'name': name,
                'email': email,
                'error': 'Name and email must be strings'
            })
            continue

        name = name.strip()
        if not name:
            rejected_entries.append({
                'index': idx,
                'name': name,
                'email': email,
                'error': 'Name cannot be empty or whitespace only'
            })
            continue

        try:
            validated_email = validate_email(email)
            normalized_email = validated_email.lower()

            if len(normalized_email) > 254:
                rejected_entries.append({
                    'index': idx,
                    'name': name,
                    'email': email,
                    'error': 'Email exceeds maximum length of 254 characters'
                })
            else:
                valid_users.append({
                    'name': name,
                    'email': normalized_email,
                    'original_email': email
                })

        except Exception as e:
            error_msg = str(e)
            if "value is not a valid email address" in error_msg:
                error_msg = "Invalid email format"
            elif "ensure this value has at most" in error_msg:
                error_msg = "Email exceeds maximum allowed length"

            rejected_entries.append({
                'index': idx,
                'name': name,
                'email': email,
                'error': error_msg
            })

    return {
        'successful': valid_users,
        'rejected': rejected_entries
    }

