from typing import SupportsInt, Any
import math

def process_measurement_pipeline(objects: list, scale_factor: float, threshold: int) -> tuple[int, bool]:
    if not isinstance(objects, list):
        raise TypeError("Input must be a list")
    if not isinstance(scale_factor, (int, float)):
        raise TypeError("Scale factor must be numeric")
    if not isinstance(threshold, int):
        raise TypeError("Threshold must be an integer")

    valid_integers = []
    overflow_occurred = False

    for obj in objects:
        try:
            if isinstance(obj, SupportsInt):
                int_value = int(obj)
            elif isinstance(obj, (int, float, str)):
                int_value = int(float(obj) if isinstance(obj, str) else obj)
            else:
                continue

            if abs(int_value) < 100:
                scaled_value = int(int_value * scale_factor)
            else:
                scaled_value = int(int_value / scale_factor) if scale_factor != 0 else 0

            valid_integers.append(scaled_value)

        except (ValueError, TypeError, OverflowError):
            continue

    if not valid_integers:
        return 0, False

    total_sum = sum(valid_integers)

    if total_sum > threshold:
        total_sum = threshold
        overflow_occurred = True

    return total_sum, overflow_occurred

import numpy as np
from typing import List

def simulate_quantum_circuit(stage_matrices: List[np.ndarray], repetitions: int) -> List[np.ndarray]:
    if repetitions <= 0:
        raise ValueError("Repetitions must be positive integer")

    valid_cumulative = []
    tolerance = 1e-10

    for idx, matrix in enumerate(stage_matrices):
        if matrix.shape[0] != matrix.shape[1]:
            raise ValueError(f"Stage {idx}: Matrix must be square")

        try:
            cumulative = np.linalg.matrix_power(matrix, repetitions)
        except np.linalg.LinAlgError:
            raise ValueError(f"Stage {idx}: Matrix power computation failed")

        identity = np.eye(matrix.shape[0])
        product = cumulative @ cumulative.conj().T
        diff = np.max(np.abs(product - identity))

        if diff > tolerance:
            raise ValueError(f"Stage {idx}: Cumulative matrix not unitary")

        valid_cumulative.append(cumulative)

    phase_angles = [np.angle(np.linalg.det(mat)) for mat in valid_cumulative]
    sorted_indices = np.argsort(phase_angles)

    return [valid_cumulative[i] for i in sorted_indices]

