from typing import Union, get_origin, get_args, _UnionGenericAlias
from collections.abc import Hashable


def are_types_equivalent(type_a: type, type_b: type) -> bool:
    if type_a is type_b:
        return True

    origin_a = get_origin(type_a)
    origin_b = get_origin(type_b)

    if origin_a is not origin_b:
        return False

    if origin_a is None:
        return type_a == type_b

    args_a = get_args(type_a)
    args_b = get_args(type_b)

    if origin_a is Union or isinstance(type_a, _UnionGenericAlias):
        if len(args_a) != len(args_b):
            return False

        a_set = set()
        b_set = set()

        for arg in args_a:
            if isinstance(arg, Hashable):
                a_set.add(arg)
            else:
                a_set.add(frozenset(get_args(arg)) if get_origin(arg) else arg)

        for arg in args_b:
            if isinstance(arg, Hashable):
                b_set.add(arg)
            else:
                b_set.add(frozenset(get_args(arg)) if get_origin(arg) else arg)

        return a_set == b_set

    if len(args_a) != len(args_b):
        return False

    return all(are_types_equivalent(a, b) for a, b in zip(args_a, args_b))

import threading
import time
from typing import List, Dict, Any

def orchestrate_batch_processing(condition: threading.Condition, shared_queue: List, new_batch: List, min_batch_size: int = 5) -> Dict[str, Any]:
    if not isinstance(new_batch, list):
        raise TypeError("new_batch must be a list")
    if min_batch_size <= 0:
        raise ValueError("min_batch_size must be positive")

    valid_data = []
    invalid_entries = []

    for item in new_batch:
        try:
            if not isinstance(item, (int, float)):
                raise TypeError(f"Non-numeric value: {item}")
            valid_data.append(float(item))
        except (TypeError, ValueError) as e:
            invalid_entries.append({"value": item, "error": str(e)})

    if not valid_data:
        raise ValueError("No valid numeric data in batch")

    notification_stats = {
        "timestamp": None,
        "threads_awakened": 0,
        "invalid_entries": invalid_entries,
        "queue_size_before": 0,
        "queue_size_after": 0
    }

    with condition:
        notification_stats["queue_size_before"] = len(shared_queue)
        shared_queue.extend(valid_data)
        notification_stats["queue_size_after"] = len(shared_queue)

        if len(shared_queue) >= min_batch_size:
            condition.notifyAll()
            notification_stats["timestamp"] = time.time()
            notification_stats["threads_awakened"] = threading.active_count() - 1

    return notification_stats

