import re
from typing import Dict, List, Tuple

def configure_boolean_switches(parser: argparse.ArgumentParser, 
                               config_definitions: List[Tuple[str, str, bool]]) -> Dict[str, bool]:
    if not isinstance(parser, argparse.ArgumentParser):
        raise TypeError("parser must be an argparse.ArgumentParser instance")
    if not isinstance(config_definitions, list):
        raise TypeError("config_definitions must be a list")

    reserved_keywords = {'help', 'version', 'verbose', 'quiet', 'debug', 'config'}
    flag_defaults = {}

    for i, (flag_name, help_text, default_value) in enumerate(config_definitions):
        if not isinstance(flag_name, str) or not isinstance(help_text, str) or not isinstance(default_value, bool):
            raise ValueError(f"Invalid type at index {i}: expected (str, str, bool)")

        if not re.match(r'^[a-zA-Z][a-zA-Z0-9_-]*$', flag_name):
            raise ValueError(f"Flag name '{flag_name}' must be alphanumeric with optional hyphens/underscores")

        if flag_name.lower() in reserved_keywords:
            raise ValueError(f"Flag name '{flag_name}' is a reserved keyword")

        if flag_name in flag_defaults:
            raise ValueError(f"Duplicate flag name '{flag_name}' detected")

        parser.add_argument(
            f'--{flag_name}',
            f'--no-{flag_name}',
            action=argparse.BooleanOptionalAction,
            default=default_value,
            help=help_text
        )
        flag_defaults[flag_name] = default_value

    return flag_defaults

