import threading
import logging
from typing import Dict, List, Optional

logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

def generate_thread_health_report(threads: List[Optional[threading.Thread]], timeout_threshold: float = 2.0) -> Dict[str, Dict[str, bool]]:
    if not isinstance(threads, list):
        raise TypeError("Threads must be provided as a list")
    if not isinstance(timeout_threshold, (int, float)) or timeout_threshold <= 0:
        raise ValueError("Timeout threshold must be a positive number")

    health_report = {}
    valid_threads = []

    for thread in threads:
        if thread is None:
            logger.warning("Encountered None thread object, skipping")
            continue
        if not isinstance(thread, threading.Thread):
            logger.warning(f"Invalid thread object type: {type(thread)}, skipping")
            continue
        valid_threads.append(thread)

    for thread in valid_threads:
        thread_id = thread.getName()
        alive_status = thread.is_alive()
        stuck_status = False

        if alive_status:
            try:
                thread.join(timeout=timeout_threshold)
                if thread.is_alive():
                    stuck_status = True
            except RuntimeError as e:
                logger.error(f"RuntimeError checking thread {thread_id}: {e}")
                stuck_status = False
            except Exception as e:
                logger.error(f"Unexpected error checking thread {thread_id}: {e}")
                stuck_status = True

        health_report[thread_id] = {
            'alive': alive_status,
            'stuck': stuck_status
        }

    return health_report

