import json
import importlib.resources
from typing import Dict, Any

def load_localized_config(package: str, locale: str, default_locale: str = 'en_US') -> dict:
    if not isinstance(package, str) or not package:
        raise ValueError("Package name must be a non-empty string")
    if not isinstance(locale, str) or not locale:
        raise ValueError("Locale must be a non-empty string")
    if not isinstance(default_locale, str) or not default_locale:
        raise ValueError("Default locale must be a non-empty string")

    config_data = None
    for target_locale in [locale, default_locale]:
        try:
            config_text = importlib.resources.read_text(package, f"{target_locale}.json")
            config_data = json.loads(config_text)
            break
        except (FileNotFoundError, ModuleNotFoundError, UnicodeDecodeError):
            continue

    if config_data is None:
        raise FileNotFoundError(f"Could not load config for locale '{locale}' or default '{default_locale}'")

    if "version" not in config_data:
        raise ValueError("Configuration must contain a 'version' key")
    if config_data.get("version") != "1.0":
        raise ValueError(f"Unsupported configuration version: {config_data.get('version')}")

    def strip_strings(obj: Any) -> Any:
        if isinstance(obj, str):
            return obj.rstrip()
        elif isinstance(obj, dict):
            return {k: strip_strings(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [strip_strings(item) for item in obj]
        return obj

    return strip_strings(config_data)

