import hashlib
import logging
from importlib.abc import ResourceReader
from typing import Optional

logger = logging.getLogger(__name__)

def verify_plugin_resources(reader, max_total_bytes: int = 10_485_760, chunk_size: int = 8192) -> dict[str, str]:
    if not isinstance(reader, ResourceReader):
        raise TypeError("reader must be a ResourceReader instance")
    if max_total_bytes <= 0:
        raise ValueError("max_total_bytes must be positive")
    if chunk_size <= 0 or chunk_size > 65536:
        raise ValueError("chunk_size must be between 1 and 65536 bytes")

    result = {}
    total_bytes_read = 0

    try:
        resources = reader.contents()
    except (AttributeError, NotImplementedError) as e:
        logger.warning(f"Reader does not support contents(): {e}")
        return result

    for resource_name in resources:
        if total_bytes_read >= max_total_bytes:
            logger.warning(f"Maximum total bytes ({max_total_bytes}) reached, skipping remaining resources")
            break

        try:
            with reader.open_resource(resource_name) as resource_file:
                sha256_hash = hashlib.sha256()
                bytes_read_for_resource = 0

                while True:
                    if total_bytes_read >= max_total_bytes:
                        logger.warning(f"Resource '{resource_name}' truncated due to total byte limit")
                        break

                    chunk = resource_file.read(chunk_size)
                    if not chunk:
                        break

                    sha256_hash.update(chunk)
                    bytes_read_for_resource += len(chunk)
                    total_bytes_read += len(chunk)

                if bytes_read_for_resource > 0:
                    result[resource_name] = sha256_hash.hexdigest()
                else:
                    logger.warning(f"Resource '{resource_name}' is empty")

        except (OSError, IOError, FileNotFoundError) as e:
            logger.warning(f"Failed to open resource '{resource_name}': {e}")
            continue
        except Exception as e:
            logger.error(f"Unexpected error processing resource '{resource_name}': {e}")
            continue

    return result

