import json
import importlib.resources
from typing import Dict, Any
import warnings

def get_merged_config_value(module_names: list[str], config_key: str, logger) -> dict:
    if not isinstance(module_names, list) or not all(isinstance(name, str) for name in module_names):
        raise TypeError("module_names must be a list of strings")
    if not isinstance(config_key, str) or not config_key:
        raise ValueError("config_key must be a non-empty string")

    merged_config: Dict[str, Any] = {}
    config_file_name = "config.json"

    for module_name in module_names:
        try:
            with importlib.resources.path(module_name, config_file_name) as config_path:
                if not config_path.exists():
                    logger.warning(f"Config file not found for module: {module_name}")
                    continue

                with open(config_path, 'r', encoding='utf-8') as f:
                    module_config = json.load(f)

                if config_key in module_config:
                    if isinstance(module_config[config_key], dict):
                        merged_config.update(module_config[config_key])
                    else:
                        logger.warning(f"Config key '{config_key}' in module {module_name} is not a dictionary")

        except ImportError:
            logger.warning(f"Module not found: {module_name}")
        except json.JSONDecodeError as e:
            logger.warning(f"Invalid JSON in config for module {module_name}: {e}")
        except Exception as e:
            logger.warning(f"Unexpected error loading config from {module_name}: {e}")

    if not merged_config:
        raise ValueError(f"No valid configuration found for key '{config_key}' across specified modules")

    if not isinstance(merged_config, dict) or len(merged_config) == 0:
        raise ValueError(f"Configuration for key '{config_key}' must be a non-empty dictionary")

    return merged_config

