import random

def roll_dice(dice_specs: list[tuple[int, int]]) -> list[int]:
    results = []
    for count, sides in dice_specs:
        if sides <= 0 or count <= 0:
            raise ValueError("Number of sides and count must be positive integers")
        for _ in range(count):
            results.append(random.randrange(1, sides + 1))
    return results

