from solution import safe_get_nested


def test_normal_case():
    """Test normal nested dictionary access."""
    data = {"a": {"b": {"c": 42}}}
    assert safe_get_nested(data, ["a", "b", "c"]) == 42


def test_shallow_access():
    """Test accessing a top-level key."""
    data = {"key": "value"}
    assert safe_get_nested(data, ["key"]) == "value"


def test_missing_key_at_first_level():
    """Test when the first key is missing."""
    data = {"a": {"b": 1}}
    assert safe_get_nested(data, ["x"]) is None
    assert safe_get_nested(data, ["x"], default=0) == 0


def test_missing_key_at_nested_level():
    """Test when a nested key is missing."""
    data = {"a": {"b": {"c": 42}}}
    assert safe_get_nested(data, ["a", "b", "x"]) is None
    assert safe_get_nested(data, ["a", "b", "x"], default="missing") == "missing"


def test_empty_keys_list():
    """Test with an empty list of keys."""
    data = {"a": 1}
    assert safe_get_nested(data, []) == data


def test_non_dict_intermediate_value():
    """Test when an intermediate value is not a dictionary."""
    data = {"a": {"b": 42}}
    assert safe_get_nested(data, ["a", "b", "c"]) is None
    assert safe_get_nested(data, ["a", "b", "c"], default=0) == 0


def test_data_is_not_dict():
    """Test when the initial data is not a dictionary."""
    assert safe_get_nested([1, 2, 3], ["0"]) is None
    assert safe_get_nested("string", ["key"], default="nope") == "nope"
    assert safe_get_nested(None, ["a"], default=0) == 0


def test_default_value_types():
    """Test various default value types."""
    data = {"a": {"b": 1}}

    # Integer default
    assert safe_get_nested(data, ["a", "c"], default=100) == 100

    # String default
    assert safe_get_nested(data, ["x"], default="not found") == "not found"

    # List default
    assert safe_get_nested(data, ["y"], default=[1, 2, 3]) == [1, 2, 3]

    # Dict default
    assert safe_get_nested(data, ["z"], default={"empty": True}) == {"empty": True}

    # None default (explicit)
    assert safe_get_nested(data, ["w"], default=None) is None


def test_none_values_in_data():
    """Test when the dictionary contains None values."""
    data = {"a": None, "b": {"c": None}}
    assert safe_get_nested(data, ["a"]) is None
    assert safe_get_nested(data, ["b", "c"]) is None
    assert safe_get_nested(data, ["b", "c", "d"]) is None


def test_falsey_values_in_data():
    """Test with falsey values (0, False, empty string)."""
    data = {"a": 0, "b": False, "c": "", "d": []}
    assert safe_get_nested(data, ["a"]) == 0
    assert safe_get_nested(data, ["b"]) is False
    assert safe_get_nested(data, ["c"]) == ""
    assert safe_get_nested(data, ["d"]) == []


def test_complex_nested_structure():
    """Test with a more complex nested structure."""
    data = {
        "users": {
            "alice": {
                "profile": {
                    "name": "Alice",
                    "age": 30,
                    "preferences": {
                        "theme": "dark",
                        "notifications": True
                    }
                }
            }
        }
    }

    # Valid paths
    assert safe_get_nested(data, ["users", "alice", "profile", "name"]) == "Alice"
    assert safe_get_nested(data, ["users", "alice", "profile", "preferences", "theme"]) == "dark"

    # Invalid paths
    assert safe_get_nested(data, ["users", "bob"]) is None
    assert safe_get_nested(data, ["users", "alice", "profile", "email"]) is None


def test_keys_with_special_characters():
    """Test keys with dots, spaces, and other characters."""
    data = {
        "key.with.dots": {
            "key with spaces": {
                "key-with-dashes": "value"
            }
        }
    }

    assert safe_get_nested(data, ["key.with.dots", "key with spaces", "key-with-dashes"]) == "value"
    assert safe_get_nested(data, ["key.with.dots", "wrong key"]) is None


def test_empty_dictionary():
    """Test with an empty dictionary."""
    data = {}
    assert safe_get_nested(data, ["any"]) is None
    assert safe_get_nested(data, []) == {}


def test_mixed_key_types_in_data():
    """Test when dictionary has non-string keys (should fail gracefully)."""
    data = {1: "one", "two": 2, (3, 4): "tuple"}

    # String keys work for string keys
    assert safe_get_nested(data, ["two"]) == 2

    # Non-string keys in the path won't be found since function expects string keys
    # The function signature is keys: list[str], so we should only test with string keys
    # Integer 1 will be converted to string "1" for key lookup
    assert safe_get_nested(data, ["1"]) is None  # String "1" not integer 1
    assert safe_get_nested(data, ["(3, 4)"]) is None  # String "(3, 4)" not tuple (3, 4)


def test_return_type_consistency():
    """Test that return type matches the found value or default."""
    data = {"a": {"b": 123}}

    # Returns int from data
    result = safe_get_nested(data, ["a", "b"])
    assert isinstance(result, int)

    # Returns string default
    result = safe_get_nested(data, ["a", "c"], default="default")
    assert isinstance(result, str)

    # Returns None default
    result = safe_get_nested(data, ["x"])
    assert result is None


def test_mutation_safety():
    """Test that the original data is not mutated by the function itself."""
    data = {"a": {"b": [1, 2, 3]}}
    original_data = {"a": {"b": [1, 2, 3]}}

    # Call the function - this should not mutate the data
    result = safe_get_nested(data, ["a", "b"])

    # The function itself doesn't mutate data, but modifying the returned value
    # will affect the original since it returns a reference
    # This test should only verify the function doesn't mutate data during execution
    assert data == original_data  # Original should be unchanged after function call

