    def test_empty_url(self) -> None:
        """Test URL without query parameters."""
        assert parse_query_parameters("https://example.com") == {}
        assert parse_query_parameters("https://example.com/") == {}
        assert parse_query_parameters("https://example.com/path") == {}

    def test_url_with_empty_query_string(self) -> None:
        """Test URL with empty query string."""
        assert parse_query_parameters("https://example.com?") == {}
        assert parse_query_parameters("https://example.com/?") == {}
        assert parse_query_parameters("https://example.com/path?") == {}

    def test_single_parameter_single_value(self) -> None:
        """Test URL with single parameter and single value."""
        url = "https://example.com?key=value"
        expected: Dict[str, List[str]] = {"key": ["value"]}
        assert parse_query_parameters(url) == expected

    def test_multiple_parameters_single_values(self) -> None:
        """Test URL with multiple parameters, each with single value."""
        url = "https://example.com?key1=value1&key2=value2&key3=value3"
        expected: Dict[str, List[str]] = {
            "key1": ["value1"],
            "key2": ["value2"],
            "key3": ["value3"]
        }
        assert parse_query_parameters(url) == expected

    def test_single_parameter_multiple_values(self) -> None:
        """Test URL with single parameter having multiple values."""
        url = "https://example.com?key=value1&key=value2&key=value3"
        expected: Dict[str, List[str]] = {"key": ["value1", "value2", "value3"]}
        assert parse_query_parameters(url) == expected

    def test_mixed_parameters_multiple_values(self) -> None:
        """Test URL with mixed parameters, some having multiple values."""
        url = "https://example.com?key1=val1&key2=val2&key1=val3&key3=val4&key2=val5"
        expected: Dict[str, List[str]] = {
            "key1": ["val1", "val3"],
            "key2": ["val2", "val5"],
            "key3": ["val4"]
        }
        assert parse_query_parameters(url) == expected

    def test_parameters_without_values(self) -> None:
        """Test URL with parameters without values."""
        url = "https://example.com?key1&key2=&key3"
        expected: Dict[str, List[str]] = {
            "key1": [""],
            "key2": [""],
            "key3": [""]
        }
        assert parse_query_parameters(url) == expected

    def test_parameters_with_special_characters(self) -> None:
        """Test URL with special characters in keys and values."""
        # Properly encode special characters that have meaning in URLs
        special_chars = "!@#$%^&*()"
        encoded_special_chars = quote(special_chars, safe='')
        url = f"https://example.com?key%20with%20spaces=value%20with%20spaces&special={encoded_special_chars}"
        expected: Dict[str, List[str]] = {
            "key with spaces": ["value with spaces"],
            "special": [special_chars]
        }
        assert parse_query_parameters(url) == expected

    def test_parameters_with_encoded_values(self) -> None:
        """Test URL with URL-encoded values."""
        url = "https://example.com?email=user%40example.com&query=hello%20world"
        expected: Dict[str, List[str]] = {
            "email": ["user@example.com"],
            "query": ["hello world"]
        }
        assert parse_query_parameters(url) == expected

    def test_parameters_with_duplicate_values(self) -> None:
        """Test URL with duplicate values for same parameter."""
        url = "https://example.com?key=value&key=value&key=value"
        expected: Dict[str, List[str]] = {"key": ["value", "value", "value"]}
        assert parse_query_parameters(url) == expected

    def test_url_with_fragment_only(self) -> None:
        """Test URL with fragment but no query parameters."""
        url = "https://example.com#section"
        assert parse_query_parameters(url) == {}

    def test_url_with_query_and_fragment(self) -> None:
        """Test URL with both query parameters and fragment."""
        url = "https://example.com?key=value#section"
        expected: Dict[str, List[str]] = {"key": ["value"]}
        assert parse_query_parameters(url) == expected

    def test_complex_url_with_all_components(self) -> None:
        """Test complete URL with all components."""
        url = "https://user:pass@example.com:8080/path/to/resource?key1=val1&key2=val2&key1=val3#fragment"
        expected: Dict[str, List[str]] = {
            "key1": ["val1", "val3"],
            "key2": ["val2"]
        }
        assert parse_query_parameters(url) == expected

    def test_case_sensitive_parameters(self) -> None:
        """Test that parameter keys are case-sensitive."""
        url = "https://example.com?KEY=value1&key=value2&Key=value3"
        expected: Dict[str, List[str]] = {
            "KEY": ["value1"],
            "key": ["value2"],
            "Key": ["value3"]
        }
        assert parse_query_parameters(url) == expected

    def test_empty_string_url(self) -> None:
        """Test empty string as URL."""
        assert parse_query_parameters("") == {}

    def test_malformed_url(self) -> None:
        """Test malformed URL string."""
        # These should still be parsed by urlparse
        url = "not a valid url?key=value"
        expected: Dict[str, List[str]] = {"key": ["value"]}
        assert parse_query_parameters(url) == expected

    def test_parameters_with_plus_sign(self) -> None:
        """Test URL with plus signs in values."""
        url = "https://example.com?query=hello+world&space=+"
        expected: Dict[str, List[str]] = {
            "query": ["hello world"],
            "space": [" "]
        }
        assert parse_query_parameters(url) == expected

    def test_parameters_with_equal_in_value(self) -> None:
        """Test URL with equals sign in parameter value."""
        url = "https://example.com?expression=a%3Db&key=value"
        expected: Dict[str, List[str]] = {
            "expression": ["a=b"],
            "key": ["value"]
        }
        assert parse_query_parameters(url) == expected

    def test_parameters_with_ampersand_in_value(self) -> None:
        """Test URL with ampersand in parameter value."""
        url = "https://example.com?query=a%26b&key=value"
        expected: Dict[str, List[str]] = {
            "query": ["a&b"],
            "key": ["value"]
        }
        assert parse_query_parameters(url) == expected

    def test_preserves_order_of_values(self) -> None:
        """Test that order of values for same parameter is preserved."""
        url = "https://example.com?colors=red&colors=blue&colors=green&colors=red"
        expected: Dict[str, List[str]] = {"colors": ["red", "blue", "green", "red"]}
        result = parse_query_parameters(url)
        assert result == expected
        assert result["colors"] == ["red", "blue", "green", "red"]

    def test_return_type(self) -> None:
        """Test that function returns correct type."""
        result = parse_query_parameters("https://example.com?key=value")
        assert isinstance(result, dict)
        assert all(isinstance(key, str) for key in result.keys())
        assert all(isinstance(value, list) for value in result.values())
