import locale
from contextlib import contextmanager
from typing import Any, Callable

@contextmanager
def temporary_locale(category: int, locale_name: str):
    """Context manager for temporarily setting a locale."""
    original_locale = locale.setlocale(category)
    try:
        locale.setlocale(category, locale_name)
        yield
    finally:
        locale.setlocale(category, original_locale)

def format_with_temporary_locale(category: int, locale_name: str, formatter: Callable) -> Any:
    """Execute a formatter with a temporary locale setting."""
    with temporary_locale(category, locale_name):
        return formatter()

