from fractions import Fraction

def find_min_abs_value(rational_strings: list[str]) -> str:
    if not rational_strings:
        raise ValueError("Input list cannot be empty")

    min_fraction = None
    min_abs_value = None

    for s in rational_strings:
        fraction = Fraction(s)
        abs_value = abs(fraction)

        if min_abs_value is None or abs_value < min_abs_value:
            min_fraction = fraction
            min_abs_value = abs_value

    return str(min_fraction)

