from functools import reduce
from typing import List

def max_subarray_volume(volumes: List[int]) -> int:
    def reducer(acc, volume):
        current_max, overall_max = acc
        current_max = max(volume, current_max + volume)
        overall_max = max(overall_max, current_max)
        return (current_max, overall_max)

    if not volumes:
        return 0

    initial = (volumes[0], volumes[0])
    _, result = reduce(reducer, volumes[1:], initial)
    return result

from email import message_from_string
from email.message import Message
from typing import Dict, List


def extract_header_values(raw_headers: str) -> Dict[str, List[str]]:
    msg: Message = message_from_string(raw_headers)
    result: Dict[str, List[str]] = {}

    for header_name, header_value in msg.items():
        normalized_name = header_name.lower()
        if normalized_name not in result:
            result[normalized_name] = []
        result[normalized_name].append(header_value)

    return result

