import inspect

def get_caller_context(levels_up: int = 1) -> tuple[str, int, str, list[str]]:
    frame = inspect.currentframe()
    for _ in range(levels_up + 1):
        if frame is None:
            break
        frame = frame.f_back

    if frame is None:
        return ("<unknown>", 0, "<unknown>", [])

    frame_info = inspect.getframeinfo(frame)
    return (
        frame_info.filename,
        frame_info.lineno,
        frame_info.function,
        frame_info.code_context or []
    )

