import types

def create_config_from_string(config_str: str) -> object:
    config_dict = {}
    for pair in config_str.split(','):
        if not pair.strip():
            continue
        key, value = pair.split('=', 1)
        config_dict[key.strip()] = value.strip()
    return types.SimpleNamespace(**config_dict)

