import xml.etree.ElementTree as ET
from typing import List

def extract_tag_text_from_xml_files(file_paths: List[str], target_tag: str) -> List[str]:
    results = []

    for file_path in file_paths:
        try:
            # Use iterparse for memory-efficient parsing
            context = ET.iterparse(file_path, events=('end',))

            for event, elem in context:
                if elem.tag == target_tag and elem.text is not None:
                    # Strip whitespace and add non-empty text
                    text = elem.text.strip()
                    if text:
                        results.append(text)

                # Clear processed elements to free memory
                elem.clear()

        except ET.ParseError:
            # Skip files with XML parsing errors
            continue
        except (FileNotFoundError, PermissionError, OSError):
            # Skip files that can't be accessed
            continue

    return results

