import os
from typing import Dict

def verify_symlinks_within_base(directory: str | os.PathLike, trusted_base: str | os.PathLike) -> Dict[str, bool]:
    result = {}

    trusted_base_canonical = os.path.realpath(trusted_base)

    for root, dirs, files in os.walk(directory):
        for name in files + dirs:
            path = os.path.join(root, name)
            if os.path.islink(path):
                try:
                    target_path = os.path.realpath(path)
                    result[path] = target_path.startswith(trusted_base_canonical)
                except OSError:
                    result[path] = False

    return result

