import inspect
from typing import Any

def capture_exception_context(exc: BaseException) -> list[dict[str, Any]]:
    traceback_info = []

    for frame_info in inspect.trace():
        frame = frame_info.frame
        frame_dict = {
            'filename': frame_info.filename,
            'lineno': frame_info.lineno,
            'function': frame_info.function,
            'code_context': frame_info.code_context,
            'index': frame_info.index,
            'locals': {}
        }

        for var_name, var_value in frame.f_locals.items():
            try:
                frame_dict['locals'][var_name] = repr(var_value)
            except Exception:
                frame_dict['locals'][var_name] = '<unrepresentable>'

        traceback_info.append(frame_dict)

    return traceback_info

