import pytest
import inspect
from unittest.mock import patch, MagicMock
from solution import capture_exception_context


def test_capture_exception_context_basic_exception():
    """Test basic exception with simple call stack."""
    try:
        x = 1
        y = 0
        result = x / y
    except ZeroDivisionError as exc:
        traceback_info = capture_exception_context(exc)

        assert isinstance(traceback_info, list)
        assert len(traceback_info) > 0

        for frame_info in traceback_info:
            assert isinstance(frame_info, dict)
            assert set(frame_info.keys()) == {'filename', 'lineno', 'function', 
                                            'code_context', 'index', 'locals'}
            assert isinstance(frame_info['filename'], str)
            assert isinstance(frame_info['lineno'], int)
            assert frame_info['lineno'] > 0
            assert isinstance(frame_info['function'], str)
            assert isinstance(frame_info['locals'], dict)

            # Check that local variables from the test are captured
            if 'x' in frame_info['locals']:
                assert frame_info['locals']['x'] == '1'
            if 'y' in frame_info['locals']:
                assert frame_info['locals']['y'] == '0'


def test_capture_exception_context_nested_functions():
    """Test exception raised from nested function calls."""
    def inner_function():
        local_var = "inner_value"
        raise ValueError("Test error")

    def outer_function():
        outer_var = "outer_value"
        inner_function()

    try:
        outer_function()
    except ValueError as exc:
        traceback_info = capture_exception_context(exc)

        # Should have frames for both inner and outer functions
        function_names = [frame['function'] for frame in traceback_info]
        assert 'inner_function' in function_names
        assert 'outer_function' in function_names

        # Check local variables in each frame
        for frame in traceback_info:
            if frame['function'] == 'inner_function':
                assert frame['locals']['local_var'] == "'inner_value'"
            elif frame['function'] == 'outer_function':
                assert frame['locals']['outer_var'] == "'outer_value'"


