            assert len(traceback_info) == 3

            for i, frame_info in enumerate(traceback_info):
                assert frame_info['filename'] == f'/test/path_{i}.py'
                assert frame_info['lineno'] == 10 + i
                assert frame_info['function'] == f'function_{i}'
                assert frame_info['locals'] == {f'var_{i}': f"'value_{i}'"}


