        KeyError("test"),
        IndexError("test"),
        AttributeError("test"),
        ZeroDivisionError("test"),
    ]

    for exc_instance in exception_types:
        # Create an actual exception instance with traceback
        try:
            raise exc_instance
        except type(exc_instance) as exc:
