import ipaddress
from typing import List


def consolidate_ipv4_networks(network_strings: List[str]) -> List[str]:
    networks = []
    for net_str in network_strings:
        try:
            network = ipaddress.IPv4Network(net_str, strict=False)
            networks.append(network)
        except ValueError:
            continue

    if not networks:
        return []

    networks = list(set(networks))
    networks.sort()

    result = []
    for i, net in enumerate(networks):
        is_subnet = False
        for j, other in enumerate(networks):
            if i != j and net.subnet_of(other):
                is_subnet = True
                break
        if not is_subnet:
            result.append(str(net))

    return result

