import re
from typing import Tuple, Dict, List

def process_text_replacements(text: str, pattern_replacements: List[Tuple[str, str]]) -> Tuple[str, Dict[str, int]]:
    replacement_counts = {}

    for pattern, replacement in pattern_replacements:
        compiled_pattern = re.compile(pattern)
        text, count = compiled_pattern.subn(replacement, text)
        replacement_counts[pattern] = count

    return text, replacement_counts

