from contextlib import ExitStack
from typing import List

def process_dynamic_resources(resource_specs: List[str], fallback: bool = False) -> List[str]:
    results = []

    with ExitStack() as stack:
        for spec in resource_specs:
            if spec.startswith("file://"):
                resource = open(spec[7:], 'r')
                stack.enter_context(resource)
                results.append(resource.read())
            elif spec.startswith("temp://"):
                import tempfile
                resource = tempfile.NamedTemporaryFile()
                stack.enter_context(resource)
                results.append(resource.name)
            else:
                if fallback:
                    results.append(f"skipped: {spec}")
                else:
                    raise ValueError(f"Unsupported resource spec: {spec}")

    return results

