import xml.etree.ElementTree as ET
from typing import List

def extract_namespaced_elements(xml_content: str, namespace_map: dict[str, str], element_names: list[str]) -> List[ET.Element]:
    root = ET.fromstring(xml_content)

    for prefix, uri in namespace_map.items():
        ET.register_namespace(prefix, uri)

    result = []
    for element_name in element_names:
        namespace_uri = None
        local_name = element_name

        if '}' in element_name:
            namespace_uri, local_name = element_name[1:].split('}', 1)

        if namespace_uri:
            xpath = f".//{{{namespace_uri}}}{local_name}"
        else:
            xpath = f".//{local_name}"

        result.extend(root.findall(xpath))

    return result

