from collections.abc import MutableSequence
from typing import Type


def validate_mutable_sequence(cls: Type) -> bool:
    """
    Validate whether a class correctly implements the mutable sequence protocol.

    Checks if the class is a subclass of MutableSequence and verifies
    that all required abstract methods are properly implemented.
    """
    if not issubclass(cls, MutableSequence):
        return False

    try:
        # Check that all abstract methods are implemented
        cls.__abstractmethods__
        # If __abstractmethods__ is not empty, the class is still abstract
        if cls.__abstractmethods__:
            return False
    except AttributeError:
        # If __abstractmethods__ doesn't exist, the class might not be properly
        # registered as an ABC subclass, so we need to check methods individually
        required_methods = {
            '__getitem__', '__setitem__', '__delitem__', '__len__',
            'insert'
        }

        # Check that all required methods are implemented
        for method in required_methods:
            if method not in cls.__dict__:
                return False

        # Check that the methods come from the class itself, not inherited
        # from a non-concrete parent (except from MutableSequence itself)
        for method in required_methods:
            method_obj = getattr(cls, method, None)
            if method_obj is None:
                return False

            # Check if the method is abstract by looking at its __isabstractmethod__ attribute
            if getattr(method_obj, '__isabstractmethod__', False):
                return False

    # Create an instance to test basic functionality
    try:
        instance = cls()

        # Test basic sequence operations
        instance.insert(0, 'test')
        if len(instance) != 1:
            return False
        if instance[0] != 'test':
            return False

        instance[0] = 'modified'
        if instance[0] != 'modified':
            return False

        del instance[0]
        if len(instance) != 0:
            return False

        # Test that it raises IndexError for invalid access
        try:
            _ = instance[0]
            return False
        except IndexError:
            pass

        return True

    except Exception:
        # Any exception during instantiation or testing indicates invalid implementation
        return False

