import asyncio
from typing import Optional

async def extract_protocol_frames(reader: asyncio.StreamReader, delimiter: bytes, max_total_size: int = 65536) -> Optional[bytes]:
    if not delimiter:
        raise ValueError("Delimiter must be non-empty")
    if not isinstance(reader, asyncio.StreamReader):
        raise TypeError("Reader must be an asyncio.StreamReader instance")
    if max_total_size <= 0:
        raise ValueError("Maximum total size must be positive")

    total_data = bytearray()
    try:
        while len(total_data) < max_total_size:
            chunk = await reader.readuntil(delimiter)
            if not chunk:
                break
            total_data.extend(chunk)
            if chunk.endswith(delimiter):
                payload = bytes(total_data[:-len(delimiter)])
                return payload
    except asyncio.IncompleteReadError as e:
        partial = e.partial
        if partial:
            total_data.extend(partial)
            if len(total_data) > 0:
                return bytes(total_data)
    except asyncio.LimitOverrunError:
        raise MemoryError(f"Frame size exceeds maximum allowed {max_total_size}")
    except ConnectionError:
        return None

    if len(total_data) > 0:
        return bytes(total_data)
    return None

import random
import math

def estimate_pi(samples: int, seed: int | None = None) -> float:
    if seed is not None:
        random.seed(seed)

    inside = 0
    for _ in range(samples):
        x = random.random() * 2 - 1
        y = random.random() * 2 - 1

        if x * x + y * y <= 1:
            inside += 1

    return 4 * inside / samples

import base64
import hashlib
import re

def generate_log_identifier(packet_data: bytes, max_length: int = 64) -> str:
    if not isinstance(packet_data, bytes):
        raise TypeError("packet_data must be bytes")
    if len(packet_data) == 0:
        raise ValueError("packet_data cannot be empty")
    if not isinstance(max_length, int) or max_length < 8:
        raise ValueError("max_length must be an integer >= 8")

    sha256_hash = hashlib.sha256(packet_data).digest()
    encoded = base64.b32hexencode(sha256_hash).decode('ascii')

    encoded = encoded.replace('=', '')
    encoded = encoded.translate(str.maketrans('', '', 'ILO0'))

    if len(encoded) > max_length:
        truncated = encoded[:max_length - 3]
        if truncated[-1].isdigit():
            truncated = truncated.rstrip('0123456789')
        encoded = truncated + '...'

    encoded = re.sub(r'[^A-Z0-9]', '', encoded, flags=re.IGNORECASE)

    if len(encoded) < 4:
        encoded = encoded.ljust(4, 'X')

    return encoded

import numpy as np
from numpy.exceptions import AxisError

def batch_axis_reduction(arrays: list, axis: int) -> list:
    if not isinstance(arrays, list):
        raise TypeError("Input must be a list")
    if len(arrays) == 0:
        raise ValueError("Input list cannot be empty")

    for idx, arr in enumerate(arrays):
        if not isinstance(arr, np.ndarray):
            raise TypeError(f"Element at index {idx} is not a numpy array")

    reduced_arrays = []
    for idx, arr in enumerate(arrays):
        ndim = arr.ndim
        if axis < -ndim or axis >= ndim:
            raise AxisError(
                axis=axis,
                ndim=ndim,
                msg_prefix=f"Array at index {idx} with shape {arr.shape}"
            )
        try:
            mean_result = np.mean(arr, axis=axis)
            if mean_result.ndim == 0:
                reduced_arrays.append(np.array([mean_result]))
            else:
                reduced_arrays.append(mean_result)
        except Exception as e:
            raise RuntimeError(f"Failed to compute mean for array at index {idx}: {str(e)}")

    return reduced_arrays

