import glob
import os
import time
from datetime import datetime, timedelta
from pathlib import Path
from typing import Iterator, List, Optional

def find_recent_logs(root_dir: str, pattern: str = "*.log", max_age_days: int = 7, exclude_dirs: Optional[List[str]] = None) -> Iterator[Path]:
    if not os.path.isdir(root_dir):
        raise ValueError(f"Root directory '{root_dir}' does not exist or is not a directory")

    if max_age_days < 0:
        raise ValueError("max_age_days must be non-negative")

    if exclude_dirs is None:
        exclude_dirs = ["archive", "backup"]

    cutoff_time = time.time() - (max_age_days * 86400)

    for file_path in glob.iglob(os.path.join(root_dir, "**", pattern), recursive=True):
        abs_path = Path(file_path).resolve()

        if any(exclude_dir in str(abs_path) for exclude_dir in exclude_dirs):
            continue

        try:
            if abs_path.stat().st_size == 0:
                continue

            if abs_path.stat().st_mtime < cutoff_time:
                continue

            yield abs_path
        except (OSError, PermissionError):
            continue

from typing import Union

def load_and_normalize_settings(raw_config: dict[str, Union[int, str, list[str]]]) -> tuple[dict[str, Union[str, list[str]]], int]:
    if not isinstance(raw_config, dict):
        raise TypeError("Input must be a dictionary")

    normalized_settings = {}
    processed_count = 0

    for key, value in raw_config.items():
        if not isinstance(key, str):
            continue

        try:
            if isinstance(value, int):
                normalized_value = str(value)
                normalized_settings[key] = normalized_value
                processed_count += 1

            elif isinstance(value, str):
                stripped_value = value.strip()
                if stripped_value:
                    normalized_settings[key] = stripped_value
                    processed_count += 1

            elif isinstance(value, list):
                filtered_list = [item.strip() for item in value if isinstance(item, str)]
                cleaned_list = [item for item in filtered_list if item]
                if cleaned_list:
                    normalized_settings[key] = cleaned_list
                    processed_count += 1

            else:
                continue

        except (AttributeError, ValueError) as e:
            continue

    return normalized_settings, processed_count

