from typing import Callable
import functools
import typing

def apply_decorators_with_exemption(decorators: list[Callable], target_func: Callable, exempt_last: bool = True) -> tuple[Callable, list[str]]:
    if not callable(target_func):
        raise TypeError("target_func must be callable")

    if not isinstance(decorators, list):
        raise TypeError("decorators must be a list")

    applied_order = []
    current_func = target_func

    for i, decorator in enumerate(decorators):
        if not callable(decorator):
            raise TypeError(f"Decorator at index {i} is not callable")

        try:
            current_func = decorator(current_func)
            applied_order.append(decorator.__name__ if hasattr(decorator, '__name__') else f"decorator_{i}")
        except Exception as e:
            raise RuntimeError(f"Failed to apply decorator at index {i}: {e}")

    if exempt_last:
        try:
            current_func = typing.no_type_check_decorator(current_func)
            applied_order.append("no_type_check_decorator")
        except Exception as e:
            raise RuntimeError(f"Failed to apply no_type_check_decorator: {e}")

    functools.update_wrapper(current_func, target_func)

    if hasattr(target_func, '__wrapped__'):
        current_func.__wrapped__ = target_func.__wrapped__

    return current_func, applied_order

