import operator
from typing import List, Dict, Any

def filter_valid_profiles(profiles: list, required_pairs: dict, forbidden_pairs: dict, name_key: str = 'profile_name') -> list:
    if not isinstance(profiles, list):
        raise TypeError("profiles must be a list")
    if not isinstance(required_pairs, dict):
        raise TypeError("required_pairs must be a dictionary")
    if not isinstance(forbidden_pairs, dict):
        raise TypeError("forbidden_pairs must be a dictionary")

    valid_profiles = []

    for idx, profile in enumerate(profiles):
        if not isinstance(profile, dict):
            continue

        if not profile:
            continue

        if not operator.contains(profile, name_key):
            continue

        has_required = all(
            operator.contains(profile, key) and profile[key] == value
            for key, value in required_pairs.items()
        )

        if not has_required:
            continue

        has_forbidden = any(
            operator.contains(profile, key) and profile[key] == value
            for key, value in forbidden_pairs.items()
        )

        if has_forbidden:
            continue

        valid_profiles.append(profile)

    valid_profiles.sort(key=lambda p: p.get(name_key, ''))

    return valid_profiles

