import plistlib
from datetime import datetime
from typing import Any

def prepare_device_configurations(device_settings: list[dict], *, include_timestamps: bool = True) -> bytes:
    if not isinstance(device_settings, list):
        raise TypeError("device_settings must be a list")

    valid_configs = []
    for idx, config in enumerate(device_settings):
        if not isinstance(config, dict):
            continue

        if 'device_id' not in config:
            continue

        if not config.get('enabled', True):
            continue

        processed_config = {}
        for key, value in config.items():
            if isinstance(value, datetime):
                if include_timestamps:
                    processed_config[key] = value.isoformat()
                else:
                    continue
            elif isinstance(value, bytes):
                processed_config[key] = value.hex() if value else None
            elif isinstance(value, (dict, list, str, int, float, bool)):
                processed_config[key] = value
            else:
                processed_config[key] = str(value)

        if processed_config:
            valid_configs.append(processed_config)

    if not valid_configs:
        return b'<?xml version="1.0" encoding="UTF-8"?>\n<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">\n<plist version="1.0">\n<array/>\n</plist>'

    return plistlib.dumps(valid_configs, sort_keys=True)

