import os
from typing import List

def validate_and_compute_relative_paths(staging_dir: str, raw_file_paths: List[str]) -> List[str]:
    if not isinstance(staging_dir, str):
        raise TypeError("staging_dir must be a string")
    if not isinstance(raw_file_paths, list):
        raise TypeError("raw_file_paths must be a list")

    staging_dir = os.path.normpath(staging_dir)
    if not os.path.isabs(staging_dir):
        raise ValueError("staging_dir must be an absolute path")

    seen_paths = set()
    result_paths = []

    for abs_path in raw_file_paths:
        if not isinstance(abs_path, str):
            continue

        normalized_path = os.path.normpath(abs_path)

        if normalized_path in seen_paths:
            continue

        if not os.path.isabs(normalized_path):
            continue

        if os.path.isdir(normalized_path):
            continue

        try:
            rel_path = os.path.relpath(normalized_path, staging_dir)
            if rel_path.startswith('..'):
                raise ValueError(f"File '{normalized_path}' is not under staging directory '{staging_dir}'")

            seen_paths.add(normalized_path)
            result_paths.append(rel_path)
        except ValueError as e:
            raise ValueError(f"File '{normalized_path}' is not under staging directory '{staging_dir}'") from e

    return result_paths

