import sysconfig
import logging
import os
from typing import Dict, List

def analyze_installation_layout(requested_categories: List[str], scheme: str = 'posix_prefix') -> Dict[str, str]:
    if not isinstance(requested_categories, list):
        raise TypeError("requested_categories must be a list")
    if not all(isinstance(cat, str) for cat in requested_categories):
        raise TypeError("All requested_categories must be strings")

    valid_schemes = {'posix_prefix', 'nt', 'posix_user', 'nt_user', 'osx_framework_user'}
    if scheme not in valid_schemes:
        raise ValueError(f"Invalid scheme '{scheme}'. Must be one of: {sorted(valid_schemes)}")

    try:
        all_paths = sysconfig.get_paths(scheme)
    except KeyError as e:
        logging.error(f"Scheme '{scheme}' not supported by sysconfig: {e}")
        raise

    result = {}
    for category in requested_categories:
        if category in all_paths:
            path = all_paths[category]
            normalized_path = os.path.normpath(path).replace('\\', '/')
            result[category] = normalized_path
        else:
            logging.warning(f"Category '{category}' not found in scheme '{scheme}' paths. Omitting.")

    if not result:
        logging.warning(f"No requested categories found in scheme '{scheme}'. Returning empty dict.")

    return result

