import importlib.resources
import importlib.resources.abc
from typing import Optional

def collect_package_resources(package_name: str, resource_extensions: Optional[set[str]] = None) -> dict[str, bytes]:
    if resource_extensions is None:
        resource_extensions = set()

    resources = {}

    try:
        package = importlib.import_module(package_name)
    except ImportError:
        return resources

    if not hasattr(package, '__spec__') or package.__spec__ is None:
        return resources

    loader = package.__spec__.loader
    if not isinstance(loader, importlib.resources.abc.TraversableResources):
        return resources

    traversable = loader.files()

    def traverse(traversable_obj, path_prefix: str = "") -> None:
        for child in traversable_obj.iterdir():
            child_name = child.name
            child_path = f"{path_prefix}/{child_name}" if path_prefix else child_name

            if child.is_dir():
                traverse(child, child_path)
            else:
                if not resource_extensions or any(child_name.endswith(ext) for ext in resource_extensions):
                    try:
                        resources[child_path] = child.read_bytes()
                    except (OSError, ValueError):
                        continue

    traverse(traversable)
    return resources

