import shlex
import re
import logging

logger = logging.getLogger(__name__)

def parse_deployment_command(command_template: str, env_vars: dict[str, str], *, posix: bool = True) -> list[str]:
    if not isinstance(command_template, str):
        raise TypeError("command_template must be a string")
    if not isinstance(env_vars, dict):
        raise TypeError("env_vars must be a dictionary")

    processed_command = command_template
    env_pattern = re.compile(r'\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?')

    def replace_env(match):
        var_name = match.group(1)
        if var_name in env_vars:
            return env_vars[var_name]
        else:
            logger.warning(f"Environment variable '{var_name}' not found, substituting empty string")
            return ''

    processed_command = env_pattern.sub(replace_env, processed_command)

    try:
        split_args = shlex.split(processed_command, posix=posix)
    except ValueError as e:
        logger.error(f"Failed to parse command after substitution: {e}")
        split_args = []

    final_args = []
    for arg in split_args:
        if arg or (command_template.find(f'"' + arg + '"') != -1 or command_template.find(f"'" + arg + "'") != -1):
            final_args.append(arg)

    return final_args

