import symtable
import ast
from typing import Dict, Tuple

def extract_class_methods(source_code: str, class_name: str) -> Dict[str, Tuple[int, int]]:
    result = {}

    # Create symbol table from source code
    table = symtable.symtable(source_code, "<string>", "exec")

    # Find the class in the symbol table
    def find_class(st):
        if isinstance(st, symtable.Class) and st.get_name() == class_name:
            return st
        for child in st.get_children():
            found = find_class(child)
            if found:
                return found
        return None

    class_table = find_class(table)
    if not class_table:
        return result

    # Get methods from the class
    methods = class_table.get_methods()

    # Parse the AST to get line numbers
    tree = ast.parse(source_code)

    # Find the class definition in AST
    class_node = None
    for node in ast.walk(tree):
        if isinstance(node, ast.ClassDef) and node.name == class_name:
            class_node = node
            break

    if not class_node:
        return result

    # Extract method names and their line numbers from the class
    for node in class_node.body:
        if isinstance(node, ast.FunctionDef):
            method_name = node.name
            # Check if this method is in the symbol table's methods
            if method_name in methods:
                # Get start and end line numbers
                start_line = node.lineno
                end_line = node.end_lineno if hasattr(node, 'end_lineno') else start_line
                result[method_name] = (start_line, end_line)

    return result

