import typing
import logging

logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

def prepare_network_payload(data_items: list[typing.SupportsBytes], delimiter: bytes = b'|') -> tuple[bytes, int]:
    if not isinstance(data_items, list):
        raise TypeError("data_items must be a list")
    if not isinstance(delimiter, bytes):
        raise TypeError("delimiter must be bytes")

    processed_items = []
    success_count = 0

    for idx, item in enumerate(data_items):
        try:
            if not hasattr(item, '__bytes__'):
                logger.warning(f"Item at index {idx} does not support bytes conversion, skipping")
                continue

            byte_data = bytes(item)
            if not isinstance(byte_data, bytes):
                logger.warning(f"Item at index {idx} returned non-bytes from __bytes__, skipping")
                continue

            processed_items.append(byte_data)
            success_count += 1

        except (TypeError, ValueError, AttributeError) as e:
            logger.warning(f"Failed to convert item at index {idx} to bytes: {e}")
            continue
        except Exception as e:
            logger.error(f"Unexpected error processing item at index {idx}: {e}")
            continue

    if not processed_items:
        return b'', 0

    concatenated = delimiter.join(processed_items)
    return concatenated, success_count

