import os
import mailbox
from pathlib import Path
from typing import Dict, Tuple

def audit_email_storage(root_path: str | os.PathLike, *, follow_symlinks: bool = False) -> dict[str, tuple[int, int]]:
    root = Path(root_path)
    if not root.exists() or not root.is_dir():
        raise ValueError(f"Invalid root directory: {root_path}")

    result = {}

    for entry in root.iterdir():
        if entry.is_symlink() and not follow_symlinks:
            continue
        if not entry.is_dir():
            continue

        try:
            maildir = mailbox.Maildir(str(entry), factory=None)
        except (mailbox.NoSuchMailboxError, OSError, ValueError):
            continue

        message_count = 0
        total_size = 0

        for key in maildir.iterkeys():
            try:
                message = maildir.get_message(key)
                message_count += 1
                message_path = maildir._lookup(key)
                if message_path and os.path.exists(message_path):
                    total_size += os.path.getsize(message_path)
            except (OSError, KeyError, mailbox.MessageError):
                continue

        result[entry.name] = (message_count, total_size)

    return result

