import email
from email import policy
from email.message import EmailMessage
from typing import Tuple, List

def extract_email_content_and_attachments(raw_message: str) -> Tuple[str, List[Tuple[str, bytes]]]:
    msg = email.message_from_string(raw_message, policy=policy.default)

    primary_text = ""
    attachments = []

    def walk_message(message: EmailMessage):
        nonlocal primary_text

        if message.is_multipart():
            for part in message.iter_parts():
                walk_message(part)
        else:
            content_disposition = message.get("Content-Disposition", "")

            if "attachment" in content_disposition or "inline" in content_disposition:
                filename = message.get_filename()
                if filename:
                    payload = message.get_payload(decode=True)
                    if payload:
                        attachments.append((filename, payload))
            else:
                content_type = message.get_content_type()
                if content_type == "text/plain" and not primary_text:
                    payload = message.get_payload(decode=True)
                    if payload:
                        primary_text = payload.decode("utf-8", errors="replace")
                elif content_type == "text/html" and not primary_text:
                    payload = message.get_payload(decode=True)
                    if payload:
                        primary_text = payload.decode("utf-8", errors="replace")

    walk_message(msg)

    return primary_text, attachments

