import os
import wave
from typing import Union

def compile_marker_report(filepaths: list[Union[str, os.PathLike]], time_limit_seconds: float = 60.0) -> dict[str, list[tuple[int, float]]]:
    if not isinstance(filepaths, list):
        raise TypeError("filepaths must be a list")
    if time_limit_seconds <= 0:
        raise ValueError("time_limit_seconds must be positive")

    report = {}

    for filepath in filepaths:
        path_str = os.fspath(filepath)
        if not os.path.exists(path_str):
            continue

        try:
            with wave.open(path_str, 'rb') as wav_file:
                frame_rate = wav_file.getframerate()
                if frame_rate <= 0:
                    continue

                markers = []
                try:
                    marker_data = wav_file.getmark()
                    if not marker_data:
                        continue

                    for marker_id, position in marker_data:
                        time_in_seconds = position / frame_rate
                        if time_in_seconds <= time_limit_seconds:
                            markers.append((marker_id, round(time_in_seconds, 3)))

                except (AttributeError, TypeError):
                    continue

                if markers:
                    markers.sort(key=lambda x: x[1])
                    report[os.path.basename(path_str)] = markers

        except (wave.Error, EOFError, OSError):
            continue

    return report

