from collections.abc import ByteString
from typing import Any, Optional, Callable, Union

def process_packet_payloads(candidates: list[Any], logger: Optional[Callable[[str], None]] = None) -> list[dict[str, Union[int, bool]]]:
    if not isinstance(candidates, list):
        raise TypeError("Input must be a list")

    if logger is not None and not callable(logger):
        raise TypeError("Logger must be callable or None")

    results = []
    processed_count = 0
    invalid_count = 0

    for idx, candidate in enumerate(candidates):
        if not isinstance(candidate, ByteString):
            if logger:
                logger(f"Candidate at index {idx} is not a valid byte sequence: {type(candidate)}")
            invalid_count += 1
            continue

        payload_length = len(candidate)
        is_empty = payload_length == 0

        checksum = 0
        if not is_empty:
            for byte_val in candidate:
                checksum = (checksum + byte_val) % 256

        result_entry = {
            'checksum': checksum,
            'length': payload_length,
            'empty': is_empty
        }

        results.append(result_entry)
        processed_count += 1

        if is_empty and logger:
            logger(f"Empty byte sequence detected at index {idx}")

    if logger:
        logger(f"Processed {processed_count} valid payloads, skipped {invalid_count} invalid entries")

    return results

