from pathlib import PurePosixPath, PureWindowsPath
import sys
import re

def validate_and_extract_filenames(path_candidates: list[str]) -> list[str]:
    if not isinstance(path_candidates, list):
        print("Warning: Input must be a list, returning empty list")
        return []

    valid_filenames = []
    malformed_pattern = re.compile(r'[\x00\x01-\x1f\x7f]')

    for candidate in path_candidates:
        if not isinstance(candidate, str):
            print(f"Warning: Skipping non-string candidate: {candidate}")
            continue

        candidate_stripped = candidate.strip()
        if not candidate_stripped:
            continue

        if malformed_pattern.search(candidate):
            print(f"Warning: Skipping path with control characters: {candidate[:50]}")
            continue

        try:
            posix_path = PurePosixPath(candidate_stripped)
            windows_path = PureWindowsPath(candidate_stripped)

            if posix_path.is_reserved() or windows_path.is_reserved():
                print(f"Warning: Skipping reserved system path: {candidate_stripped}")
                continue

            if any(part == '..' or part == '.' for part in posix_path.parts):
                print(f"Warning: Skipping path with relative components: {candidate_stripped}")
                continue

            if posix_path.name:
                valid_filenames.append(posix_path.name)
            else:
                print(f"Warning: Path has no filename component: {candidate_stripped}")

        except (ValueError, RuntimeError) as e:
            print(f"Warning: Error processing path '{candidate_stripped[:30]}': {e}")
            continue

    return valid_filenames

import asyncio
from typing import Callable, Awaitable, Tuple

class UDPProtocol(asyncio.DatagramProtocol):
    def __init__(self, processor: Callable[[bytes], Awaitable[bytes]]):
        self.processor = processor
        self.transport = None

    def connection_made(self, transport: asyncio.DatagramTransport):
        self.transport = transport

    def datagram_received(self, data: bytes, addr: Tuple[str, int]):
        async def process_and_send():
            try:
                response = await self.processor(data)
                self.transport.sendto(response, addr)
            except Exception:
                pass

        asyncio.create_task(process_and_send())

    def error_received(self, exc: Exception):
        pass

    def connection_lost(self, exc: Exception):
        pass

def create_udp_echo_service(
    host: str, 
    port: int, 
    processor: Callable[[bytes], Awaitable[bytes]]
) -> Tuple[asyncio.DatagramTransport, asyncio.DatagramProtocol]:

    loop = asyncio.get_event_loop()

    async def create_endpoint():
        transport, protocol = await loop.create_datagram_endpoint(
            lambda: UDPProtocol(processor),
            local_addr=(host, port)
        )
        return transport, protocol

    return loop.run_until_complete(create_endpoint())

