import locale
from typing import Optional

def generate_localized_config(approved_languages: list[str] = None, default_key: str = "config_default") -> tuple[dict[str, str], tuple[str, str] | None]:
    if approved_languages is None:
        approved_languages = ["en", "es", "fr", "de", "ja", "zh"]

    log_info = None
    final_key = default_key

    try:
        current_locale = locale.getlocale()
        if not current_locale or len(current_locale) < 2:
            return ({final_key: "default_configuration"}, log_info)

        language, territory = current_locale[0], current_locale[1]
        if not language or not territory:
            return ({final_key: "default_configuration"}, log_info)

        normalized_lang = language.lower().replace('-', '_')
        normalized_terr = territory.lower().replace('-', '_')
        log_info = (f"{language}_{territory}", f"{normalized_lang}_{normalized_terr}")

        if normalized_lang in approved_languages:
            final_key = f"config_{normalized_lang}_{normalized_terr}"
        else:
            final_key = default_key
    except (ValueError, TypeError, AttributeError):
        final_key = default_key

    config_dict = {final_key: f"localized_config_for_{final_key}"}
    return (config_dict, log_info)

import ast
import os
import sys
from typing import List, Dict

def detect_shadowing_imports(script_path: str) -> Dict[str, List[str]]:
    """
    Analyze a Python script's imports for potential shadowing conflicts
    with the script's own filename.

    Returns a dictionary with two keys:
    - 'shadowed_imports': List of imported module names that conflict with script name
    - 'shadowing_script': The script's filename (without .py extension)
    """
    result: Dict[str, List[str]] = {
        'shadowed_imports': [],
        'shadowing_script': []
    }

    if not os.path.exists(script_path):
        return result

    # Get the script's filename without extension
    script_name = os.path.splitext(os.path.basename(script_path))[0]
    result['shadowing_script'] = [script_name]

    try:
        with open(script_path, 'r', encoding='utf-8') as file:
            content = file.read()

        # Parse the script to extract import statements
        tree = ast.parse(content)

        # Collect all imported module names
        imported_modules = set()

        for node in ast.walk(tree):
            if isinstance(node, ast.Import):
                for alias in node.names:
                    imported_modules.add(alias.name.split('.')[0])
            elif isinstance(node, ast.ImportFrom):
                if node.module:
                    imported_modules.add(node.module.split('.')[0])

        # Check for conflicts
        for module in imported_modules:
            if module == script_name:
                result['shadowed_imports'].append(module)

    except (SyntaxError, UnicodeDecodeError, OSError):
        # If we can't parse the file, return empty results
        pass

    return result

