import logging
from typing import Optional, List, Tuple
from typing import SupportsComplex

def process_complex_candidates(candidates: list, logger: Optional[logging.Logger] = None) -> tuple[list[complex], complex]:
    if logger is None:
        logger = logging.getLogger(__name__)

    if not isinstance(candidates, list):
        raise TypeError("Input must be a list")

    valid_complexes = []
    total_sum = complex(0, 0)

    for idx, candidate in enumerate(candidates):
        try:
            if isinstance(candidate, SupportsComplex):
                complex_val = complex(candidate)
                if not isinstance(complex_val, complex):
                    logger.warning(f"Candidate at index {idx} supports complex but returned non-complex: {candidate}")
                    continue
                valid_complexes.append(complex_val)
                total_sum += complex_val
            else:
                logger.debug(f"Skipping non-complex candidate at index {idx}: {type(candidate).__name__}")
        except (TypeError, ValueError) as e:
            logger.warning(f"Failed to convert candidate at index {idx} to complex: {candidate}. Error: {e}")
        except Exception as e:
            logger.error(f"Unexpected error processing candidate at index {idx}: {e}")

    logger.info(f"Processed {len(candidates)} candidates, found {len(valid_complexes)} valid complex numbers")
    return valid_complexes, total_sum

