from pathlib import Path, PurePath
import os
from typing import Dict, List

def index_files_by_extension(base_dir: str, file_paths: List[str], skip_errors: bool = True) -> Dict[str, List[str]]:
    result: Dict[str, List[str]] = {}

    if not base_dir or not isinstance(base_dir, str):
        return result

    if not file_paths or not isinstance(file_paths, list):
        return result

    try:
        base_path = Path(base_dir).resolve()
        if not base_path.exists() or not base_path.is_dir():
            return result
    except (OSError, ValueError):
        return result

    for file_path in file_paths:
        if not isinstance(file_path, str) or not file_path.strip():
            if not skip_errors:
                return {}
            continue

        try:
            current_path = Path(file_path).resolve()
            relative_path = current_path.relative_to(base_path)

            if current_path.is_file():
                extension = current_path.suffix.lower()
                if extension == '':
                    extension = '.no_extension'

                if extension not in result:
                    result[extension] = []
                result[extension].append(str(relative_path))

        except (ValueError, OSError):
            if not skip_errors:
                return {}
            continue

    return result

