import attrs

logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

def load_and_validate_config(env_dict: dict[str, Any], file_dict: dict[str, Any], required_keys: list[str]) -> dict[str, Any]:
    if not isinstance(env_dict, dict) or not isinstance(file_dict, dict):
        raise TypeError("Both env_dict and file_dict must be dictionaries")
    if not isinstance(required_keys, list) or not all(isinstance(k, str) for k in required_keys):
        raise TypeError("required_keys must be a list of strings")

    merged = file_dict.copy()
    merged.update(env_dict)

    cleaned = {}
    for key, value in merged.items():
        try:
            if isinstance(value, str):
                cleaned[key] = attrs.converters.to_bool(value)
            elif isinstance(value, bool):
                cleaned[key] = value
            else:
                cleaned[key] = value
        except (ValueError, TypeError):
            logger.warning(f"Unrecognized boolean format for key '{key}': {value}. Defaulting to False.")
            cleaned[key] = False

    missing_keys = [k for k in required_keys if k not in cleaned]
    if missing_keys:
        raise ValueError(f"Missing required configuration keys: {missing_keys}")

    return cleaned

