import http.client
import json
import urllib.parse
from typing import Dict, Any


def validate_health_endpoint(url: str, expected_status: int = 200) -> dict:
    parsed_url = urllib.parse.urlparse(url)

    if parsed_url.scheme == 'https':
        conn = http.client.HTTPSConnection(parsed_url.netloc)
    else:
        conn = http.client.HTTPConnection(parsed_url.netloc)

    path = parsed_url.path
    if parsed_url.query:
        path += '?' + parsed_url.query

    try:
        conn.request('GET', path)
        response = conn.getresponse()

        if response.status != expected_status:
            raise ValueError(
                f"Expected status {expected_status}, got {response.status}"
            )

        raw_data = response.read()
        content_type = response.getheader('Content-Type', '')

        if 'application/json' not in content_type:
            raise ValueError(
                f"Expected JSON response, got Content-Type: {content_type}"
            )

        try:
            data = json.loads(raw_data.decode('utf-8'))
        except json.JSONDecodeError as e:
            raise ValueError(f"Invalid JSON response: {e}")

        if not isinstance(data, dict):
            raise ValueError("Response is not a JSON object")

        if data.get('status') != 'ok':
            raise ValueError(
                f"Expected 'status': 'ok', got {data.get('status')}"
            )

        return data

    finally:
        conn.close()

from html.parser import HTMLParser
from typing import Optional

class SafeTextExtractor(HTMLParser):
    def __init__(self, ignore_tags: Optional[set[str]] = None):
        super().__init__()
        self.ignore_tags = ignore_tags or set()
        self.result = []
        self.ignore_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, Optional[str]]]) -> None:
        if tag.lower() in self.ignore_tags:
            self.ignore_depth += 1

    def handle_endtag(self, tag: str) -> None:
        if tag.lower() in self.ignore_tags and self.ignore_depth > 0:
            self.ignore_depth -= 1

    def handle_data(self, data: str) -> None:
        if self.ignore_depth == 0:
            self.result.append(data)

    def get_text(self) -> str:
        return ''.join(self.result)

def extract_safe_text(html_content: str, ignore_tags: set[str] = None) -> str:
    if ignore_tags is None:
        ignore_tags = {'script', 'style'}
    else:
        ignore_tags = {tag.lower() for tag in ignore_tags}

    parser = SafeTextExtractor(ignore_tags)
    parser.feed(html_content)
    return parser.get_text()

import getpass
import re
from datetime import datetime, timezone
from typing import Dict, Any, Optional

def generate_org_onboarding_id(organization_domain: str, timestamp_override: Optional[str] = None) -> Dict[str, Any]:
    if not organization_domain or not isinstance(organization_domain, str):
        raise ValueError("Organization domain must be a non-empty string")

    if '.' not in organization_domain:
        raise ValueError("Organization domain must contain at least one dot")

    try:
        operator_username = getpass.getuser()
    except (OSError, KeyError):
        operator_username = "system"

    if timestamp_override:
        try:
            timestamp_dt = datetime.fromisoformat(timestamp_override.replace('Z', '+00:00'))
            if timestamp_dt.tzinfo is None:
                timestamp_dt = timestamp_dt.replace(tzinfo=timezone.utc)
        except ValueError:
            timestamp_dt = datetime.now(timezone.utc)
    else:
        timestamp_dt = datetime.now(timezone.utc)

    timestamp_str = timestamp_dt.strftime("%Y%m%d%H%M%S")

    sanitized_domain = re.sub(r'[^a-zA-Z0-9.-]', '', organization_domain.lower())
    sanitized_domain = re.sub(r'\.+', '.', sanitized_domain)

    identifier = f"{operator_username.lower()}-{timestamp_str}-{sanitized_domain}"

    return {
        "identifier": identifier,
        "metadata": {
            "operator_username": operator_username,
            "timestamp_utc": timestamp_dt.isoformat(),
            "sanitized_domain": sanitized_domain,
            "original_domain": organization_domain,
            "timestamp_source": "override" if timestamp_override else "generated"
        }
    }

