import statistics
from typing import List, Tuple, Optional

def analyze_production_consistency(batches: List[List[float]]) -> Tuple[List[Optional[float]], List[int]]:
    if not batches:
        raise ValueError("No batches provided for analysis")

    metrics = []
    valid_indices = []

    for i, batch in enumerate(batches):
        if not isinstance(batch, list):
            metrics.append(None)
            continue

        if len(batch) < 5:
            metrics.append(None)
            continue

        all_positive = True
        for value in batch:
            if not isinstance(value, (int, float)) or value <= 0:
                all_positive = False
                break

        if not all_positive:
            metrics.append(None)
            continue

        try:
            if len(batch) == 1:
                dispersion = 0.0
            else:
                dispersion = statistics.stdev(batch)
            metrics.append(round(dispersion, 6))
            valid_indices.append(i)
        except statistics.StatisticsError:
            metrics.append(None)

    if not valid_indices:
        raise ValueError("All batches are invalid for analysis")

    valid_metrics = [metrics[i] for i in valid_indices]
    min_dispersion = min(valid_metrics)
    best_machines = [valid_indices[i] for i, metric in enumerate(valid_metrics) 
                     if abs(metric - min_dispersion) < 1e-10]

    return metrics, best_machines

import statistics
from typing import List

def assess_batch_consistency(raw_readings: List[float], valid_min: float, valid_max: float, tolerance: float, min_valid_samples: int = 5) -> tuple[bool, str]:
    if not isinstance(raw_readings, list):
        raise TypeError("raw_readings must be a list")
    if valid_min >= valid_max:
        raise ValueError("valid_min must be less than valid_max")
    if tolerance < 0:
        raise ValueError("tolerance must be non-negative")
    if min_valid_samples < 1:
        raise ValueError("min_valid_samples must be at least 1")

    valid_readings = [r for r in raw_readings if valid_min <= r <= valid_max]

    if len(valid_readings) < min_valid_samples:
        return (True, f"Insufficient valid data: {len(valid_readings)} samples remain, need at least {min_valid_samples}")

    if len(valid_readings) == 1:
        return (False, "Single valid reading - consistency check passed")

    try:
        data_variance = statistics.variance(valid_readings)
        std_dev = data_variance ** 0.5
        mean_val = sum(valid_readings) / len(valid_readings)
        cv = std_dev / mean_val if mean_val != 0 else float('inf')

        if cv > tolerance:
            return (True, f"Excessive dispersion: coefficient of variation {cv:.4f} exceeds tolerance {tolerance}")
        else:
            return (False, f"Batch acceptable: {len(valid_readings)} valid readings, CV={cv:.4f}")
    except statistics.StatisticsError as e:
        return (True, f"Statistical analysis failed: {str(e)}")

from datetime import datetime, timezone, timedelta
import re
from typing import Dict, Any, Optional

def process_log_entry(log_data: dict) -> dict:
    if not isinstance(log_data, dict):
        raise ValueError("Input must be a dictionary")

    required_keys = {"timestamp", "region", "event"}
    if not required_keys.issubset(log_data.keys()):
        missing = required_keys - set(log_data.keys())
        raise KeyError(f"Missing required keys: {missing}")

    timestamp_str = str(log_data["timestamp"]).strip()
    region = str(log_data["region"])
    event = str(log_data["event"])

    if not timestamp_str:
        raise ValueError("Timestamp string cannot be empty")

    try:
        parsed_dt = datetime.fromisoformat(timestamp_str)
    except ValueError as e:
        raise ValueError(f"Invalid ISO 8601 timestamp format: {timestamp_str}") from e

    if parsed_dt.tzinfo is not None:
        normalized_dt = parsed_dt.astimezone(timezone.utc)
        is_aware = True
    else:
        normalized_dt = parsed_dt.replace(tzinfo=None)
        is_aware = False

    if not re.match(r'^[A-Z]{2,3}-[0-9]{1,3}$', region):
        raise ValueError(f"Invalid region format: {region}")

    if len(event) > 1000:
        event = event[:997] + "..."

    return {
        "timestamp": normalized_dt,
        "region": region,
        "event": event,
        "is_aware": is_aware,
        "processed_at": datetime.now(timezone.utc)
    }

