import mimetypes
import re

def process_custom_file_types(mime_db, file_extensions: list[str], type_mapping: dict[str, str]) -> dict[str, dict[str, str]]:
    if not isinstance(file_extensions, list) or not isinstance(type_mapping, dict):
        raise TypeError("file_extensions must be a list and type_mapping must be a dictionary")

    result = {}
    mime_pattern = re.compile(r'^[a-zA-Z0-9!#$&^_.+-]+/[a-zA-Z0-9!#$&^_.+-]+$')

    for ext in file_extensions:
        if not ext or not isinstance(ext, str):
            continue

        ext_normalized = ext.lower().lstrip('.')

        if ext_normalized in mime_db.types_map[True]:
            result[ext] = {"status": "skipped", "mime_type": mime_db.types_map[True][ext_normalized]}
            continue

        if ext not in type_mapping:
            result[ext] = {"status": "error", "message": "No MIME type mapping provided"}
            continue

        mime_type = type_mapping[ext]

        if not mime_pattern.match(mime_type):
            result[ext] = {"status": "error", "message": f"Malformed MIME type: {mime_type}"}
            continue

        try:
            mime_db.add_type(mime_type, f".{ext_normalized}", strict=True)
            registered_type = mime_db.guess_type(f"test.{ext_normalized}")[0]
            result[ext] = {"status": "registered", "mime_type": registered_type}
        except Exception as e:
            result[ext] = {"status": "error", "message": f"Registration failed: {str(e)}"}

    return result

