import asyncio
from typing import Optional, Callable

def assess_event_loop_policy_compatibility(
    service_ids: list[str], 
    compatibility_checker: Callable,
    default_policy_factory: Optional[Callable] = None
) -> dict[str, tuple[str, bool, Optional[str]]]:
    if not isinstance(service_ids, list):
        raise TypeError("service_ids must be a list")
    if not callable(compatibility_checker):
        raise TypeError("compatibility_checker must be callable")

    results = {}
    default_policy = None
    if default_policy_factory is not None:
        try:
            default_policy = default_policy_factory()
        except Exception as e:
            default_policy = asyncio.DefaultEventLoopPolicy()

    for service_id in service_ids:
        if not isinstance(service_id, str):
            results[service_id] = ("", False, f"Invalid service ID type: {type(service_id)}")
            continue

        error_msg = None
        policy = None

        try:
            policy = asyncio.get_event_loop_policy()
            policy_name = policy.__class__.__name__
        except (RuntimeError, AttributeError, Exception) as e:
            error_msg = str(e)
            if default_policy is not None:
                policy = default_policy
                policy_name = policy.__class__.__name__
            else:
                policy_name = "UnknownPolicy"

        try:
            if policy is not None:
                compatible = compatibility_checker(policy)
            else:
                compatible = False
        except Exception as e:
            compatible = False
            if error_msg is None:
                error_msg = f"Checker failed: {str(e)}"
            else:
                error_msg += f"; Checker failed: {str(e)}"

        results[service_id] = (policy_name, compatible, error_msg)

    return results

