import shutil
import logging
from typing import Optional, Union

def check_required_tools(tool_names: list[str], logger: Optional[logging.Logger] = None) -> dict[str, dict[str, Union[str, bool, None]]]:
    if not isinstance(tool_names, list):
        if logger:
            logger.warning(f"Expected list but got {type(tool_names).__name__}")
        return {}

    valid_tools = []
    for idx, tool in enumerate(tool_names):
        if not isinstance(tool, str):
            if logger:
                logger.warning(f"Tool at index {idx} is not a string: {type(tool).__name__}")
            continue
        stripped_tool = tool.strip()
        if not stripped_tool:
            if logger:
                logger.warning(f"Empty tool name at index {idx}")
            continue
        valid_tools.append(stripped_tool)

    result = {}
    for tool in valid_tools:
        try:
            path = shutil.which(tool)
            if path:
                result[tool] = {
                    "path": path,
                    "available": True,
                    "error": None
                }
            else:
                result[tool] = {
                    "path": None,
                    "available": False,
                    "error": f"'{tool}' not found in PATH"
                }
        except Exception as e:
            if logger:
                logger.warning(f"Error checking tool '{tool}': {e}")
            result[tool] = {
                "path": None,
                "available": False,
                "error": f"check failed: {str(e)}"
            }

    return result

