import sys
import sysconfig
import platform
import logging

def generate_python_environment_report(suppress_warnings: bool = False) -> dict:
    if not suppress_warnings:
        logging.basicConfig(level=logging.WARNING)

    report = {}
    non_standard_chars = []

    try:
        platform_name = platform.platform()
        if not platform_name or len(platform_name.strip()) == 0:
            raise ValueError("Platform name cannot be empty")
        report['platform'] = platform_name
    except Exception as e:
        if not suppress_warnings:
            logging.warning(f"Failed to get platform: {e}")
        report['platform'] = "unknown"
        non_standard_chars.append("platform_detection_failed")

    version_info = sys.version_info
    report['normalized_version'] = f"{version_info.major}.{version_info.minor}"

    dev_build_flag = None
    try:
        dev_build_flag = sysconfig.is_python_build()
        report['is_development_build'] = dev_build_flag
    except AttributeError:
        if not suppress_warnings:
            logging.warning("sysconfig.is_python_build() not available")
        report['is_development_build'] = None
        non_standard_chars.append("missing_dev_build_check")
    except Exception as e:
        if not suppress_warnings:
            logging.warning(f"Error checking development build: {e}")
        report['is_development_build'] = None
        non_standard_chars.append("dev_build_check_failed")

    if version_info.releaselevel != 'final':
        non_standard_chars.append(f"non_final_release_{version_info.releaselevel}")

    if hasattr(sys, 'base_prefix') and sys.base_prefix != sys.prefix:
        non_standard_chars.append("virtual_environment")

    if platform.python_implementation() != 'CPython':
        non_standard_chars.append(f"non_cpython_{platform.python_implementation()}")

    report['non_standard_characteristics'] = non_standard_chars
    return report

