from inspect import signature, Parameter
from typing import Callable, Any, Union

def validate_kwargs_acceptance(callable_obj: Callable, provided_kwargs: dict[str, Any]) -> dict[str, Union[bool, str, list[str]]]:
    try:
        sig = signature(callable_obj)
    except ValueError:
        return {
            "valid": False,
            "error": "Unable to inspect callable signature",
            "matched": [],
            "invalid": list(provided_kwargs.keys()),
            "unfilled": []
        }

    parameters = sig.parameters
    matched = []
    invalid = []
    unfilled = []

    for param_name, param in parameters.items():
        if param_name in provided_kwargs:
            matched.append(param_name)
        elif param.default is Parameter.empty and param.kind not in (Parameter.VAR_POSITIONAL, Parameter.VAR_KEYWORD):
            unfilled.append(param_name)

    for kwarg in provided_kwargs:
        if kwarg not in parameters:
            if Parameter.VAR_KEYWORD in (p.kind for p in parameters.values()):
                matched.append(kwarg)
            else:
                invalid.append(kwarg)

    for param_name in matched[:]:
        if param_name in parameters:
            param = parameters[param_name]
            if param.kind in (Parameter.POSITIONAL_ONLY, Parameter.VAR_POSITIONAL):
                matched.remove(param_name)
                invalid.append(param_name)

    valid = len(invalid) == 0 and len(unfilled) == 0

    return {
        "valid": valid,
        "matched": matched,
        "invalid": invalid,
        "unfilled": unfilled
    }

