import logging
from typing import Dict

# Internal counter for logged events per user
_user_event_counters: Dict[str, int] = {}

def log_suspicious_activity(user_id: str, stage: str, severity: float, rule_ids: list[str], threshold: float = 0.3) -> None:
    # Input validation
    if not isinstance(user_id, str) or not user_id.strip():
        raise ValueError("user_id must be a non-empty string")
    if not isinstance(stage, str) or not stage.strip():
        raise ValueError("stage must be a non-empty string")
    if not isinstance(severity, (int, float)) or not 0.0 <= severity <= 1.0:
        raise ValueError("severity must be a float between 0.0 and 1.0")
    if not isinstance(rule_ids, list) or not all(isinstance(r, str) for r in rule_ids):
        raise ValueError("rule_ids must be a list of strings")
    if not isinstance(threshold, (int, float)) or not 0.0 <= threshold <= 1.0:
        raise ValueError("threshold must be a float between 0.0 and 1.0")

    # Filter low-severity events
    if severity < threshold:
        return

    # Convert severity to human-readable level
    if severity >= 0.8:
        severity_level = "CRITICAL"
    elif severity >= 0.6:
        severity_level = "HIGH"
    elif severity >= 0.4:
        severity_level = "MEDIUM"
    else:
        severity_level = "LOW"

    # Update user event counter
    _user_event_counters[user_id] = _user_event_counters.get(user_id, 0) + 1

    # Prepare rule IDs string
    rule_ids_str = ", ".join(sorted(set(rule_ids))) if rule_ids else "none"

    # Log the structured warning
    logging.warning(
        f"Suspicious activity detected - User: {user_id}, "
        f"Stage: {stage}, Severity: {severity_level} ({severity:.2f}), "
        f"Rules: [{rule_ids_str}], "
        f"User session count: {_user_event_counters[user_id]}"
    )

