import typing
from collections import defaultdict

def validate_packet_batch(capture_buffers: list[typing.Any]) -> tuple[list[typing.ByteString], dict[str, int]]:
    if not isinstance(capture_buffers, list):
        raise TypeError("Input must be a list")

    valid_packets = []
    rejection_counts = defaultdict(int)

    for idx, buffer in enumerate(capture_buffers):
        if not isinstance(buffer, typing.ByteString):
            rejection_counts["type_error"] += 1
            continue

        try:
            byte_data = bytes(buffer)
        except (TypeError, ValueError):
            rejection_counts["type_error"] += 1
            continue

        if len(byte_data) < 6:
            rejection_counts["length_error"] += 1
            continue

        if len(byte_data) > 0 and byte_data[0] != 0xAA:
            rejection_counts["delimiter_error"] += 1
            continue

        valid_packets.append(byte_data)

    summary = {
        "type_error": rejection_counts["type_error"],
        "length_error": rejection_counts["length_error"],
        "delimiter_error": rejection_counts["delimiter_error"]
    }

    return valid_packets, summary

