import wave
import os
from typing import List, Dict, Tuple

def analyze_audio_batch(filepaths: List[str], min_duration_sec: float) -> Tuple[List[Dict], List[str]]:
    if not isinstance(filepaths, list):
        raise TypeError("filepaths must be a list of strings")
    if not isinstance(min_duration_sec, (int, float)) or min_duration_sec < 0:
        raise ValueError("min_duration_sec must be a non-negative number")

    valid_files = []
    error_log = []

    for filepath in filepaths:
        if not isinstance(filepath, str) or not os.path.exists(filepath):
            error_log.append(f"Invalid or missing file: {filepath}")
            continue

        try:
            with wave.open(filepath, 'rb') as wav_file:
                n_channels = wav_file.getnchannels()
                sample_width = wav_file.getsampwidth() * 8
                frame_rate = wav_file.getframerate()
                n_frames = wav_file.getnframes()
                duration = n_frames / float(frame_rate)

                if n_channels == 2 and sample_width >= 16 and duration > min_duration_sec:
                    bitrate = (frame_rate * sample_width * n_channels) / 1000.0
                    valid_files.append({
                        'filename': os.path.basename(filepath),
                        'bitrate_kbps': round(bitrate, 2)
                    })

        except (wave.Error, OSError, EOFError) as e:
            error_log.append(f"Failed to process {filepath}: {str(e)}")
            continue
        except Exception as e:
            error_log.append(f"Unexpected error with {filepath}: {str(e)}")
            continue

    return valid_files, error_log

