from typing import Any, get_origin, get_args, Union
from collections.abc import Collection, Sequence, Mapping, Set
import sys

def validate_generic_collection(collection: Any, expected_type: type) -> bool:
    def check_type(obj: Any, target_type: type) -> bool:
        origin = get_origin(target_type)

        if origin is None:
            return isinstance(obj, target_type)

        if not isinstance(obj, origin):
            return False

        args = get_args(target_type)
        if not args:
            return True

        if origin in (list, tuple, set, frozenset, Sequence, Collection, Set):
            if origin is tuple:
                if len(args) == 2 and args[1] is ...:
                    return all(check_type(item, args[0]) for item in obj)
                else:
                    if len(obj) != len(args):
                        return False
                    return all(check_type(item, arg) for item, arg in zip(obj, args))
            else:
                return all(check_type(item, args[0]) for item in obj)

        elif origin in (dict, Mapping):
            key_type, value_type = args
            return all(
                check_type(key, key_type) and check_type(value, value_type)
                for key, value in obj.items()
            )

        elif origin is Union:
            return any(check_type(obj, arg) for arg in args)

        return True

    if not isinstance(collection, Collection):
        return False

    return check_type(collection, expected_type)

import unittest
from typing import List, Dict, Tuple, Union
import math

def analyze_sensor_similarity(readings: List[Union[int, float]], tolerance_places: int = 6, min_readings: int = 2) -> Dict:
    if not isinstance(readings, list):
        raise TypeError("readings must be a list")
    if len(readings) < min_readings:
        return {"error": f"Batch must contain at least {min_readings} readings", "problematic_pairs": []}

    valid_readings = []
    for i, val in enumerate(readings):
        if not isinstance(val, (int, float)):
            continue
        if math.isnan(val) or math.isinf(val):
            continue
        valid_readings.append((i, float(val)))

    if len(valid_readings) < 2:
        return {"error": "Insufficient valid readings after filtering", "problematic_pairs": []}

    problematic_pairs = []
    test_case = unittest.TestCase()

    for i in range(len(valid_readings)):
        idx_i, val_i = valid_readings[i]
        for j in range(i + 1, len(valid_readings)):
            idx_j, val_j = valid_readings[j]
            try:
                test_case.assertNotAlmostEqual(val_i, val_j, places=tolerance_places)
            except AssertionError:
                difference = abs(val_i - val_j)
                problematic_pairs.append({
                    "indices": (idx_i, idx_j),
                    "values": (val_i, val_j),
                    "difference": difference
                })

    return {
        "total_readings": len(readings),
        "valid_readings": len(valid_readings),
        "problematic_pairs": problematic_pairs,
        "tolerance_places": tolerance_places
    }

