import multiprocessing
import sys
import warnings
from typing import Dict, Any, Optional, List

def initialize_parallel_environment(requested_method: str, allow_override: bool = False,
                                   platform_override: Optional[str] = None) -> Dict[str, Any]:
    if not isinstance(requested_method, str):
        raise TypeError("requested_method must be a string")
    if platform_override is not None and not isinstance(platform_override, str):
        raise TypeError("platform_override must be a string or None")

    warnings_list: List[str] = []
    current_platform = platform_override if platform_override else sys.platform
    available_methods = multiprocessing.get_all_start_methods()

    if requested_method not in available_methods:
        warnings_list.append(f"Requested method '{requested_method}' not available on platform '{current_platform}'")
        if 'fork' in available_methods and current_platform.startswith('linux'):
            fallback_method = 'fork'
        elif 'spawn' in available_methods:
            fallback_method = 'spawn'
        else:
            fallback_method = available_methods[0] if available_methods else 'spawn'
        warnings_list.append(f"Using fallback method: {fallback_method}")
        actual_method = fallback_method
    else:
        actual_method = requested_method

    try:
        multiprocessing.set_start_method(actual_method, force=allow_override)
    except RuntimeError as e:
        if "context has already been set" in str(e):
            current_method = multiprocessing.get_start_method()
            if current_method != actual_method and not allow_override:
                warnings_list.append(f"Start method already set to '{current_method}'. Override not allowed.")
                actual_method = current_method
            elif allow_override:
                multiprocessing.set_start_method(actual_method, force=True)
                warnings_list.append(f"Overridden existing start method with '{actual_method}'")
        else:
            raise

    return {
        'method_used': actual_method,
        'requested_method': requested_method,
        'available_methods': available_methods,
        'platform': current_platform,
        'warnings': warnings_list,
        'override_allowed': allow_override
    }

