import os
import mimetypes
from typing import Union

def generate_upload_batch_report(file_paths: list[Union[str, os.PathLike]], allowed_prefixes: set[str]) -> list[dict[str, Union[str, bool, None]]]:
    if not isinstance(file_paths, list):
        raise TypeError("file_paths must be a list")
    if not isinstance(allowed_prefixes, set):
        raise TypeError("allowed_prefixes must be a set")

    report = []
    for path in file_paths:
        try:
            normalized_path = os.path.normpath(str(path))

            if not os.path.exists(normalized_path):
                mime_type = None
                category = 'unknown'
                is_permitted = False
                error = "File not found"
            else:
                mime_type = mimetypes.guess_file_type(normalized_path, strict=False)

                if mime_type is None:
                    category = 'unknown'
                    is_permitted = False
                    error = "Cannot detect MIME type"
                else:
                    category_map = {
                        'image/': 'image',
                        'text/': 'document',
                        'application/pdf': 'document',
                        'application/zip': 'archive',
                        'application/x-rar-compressed': 'archive',
                        'application/x-tar': 'archive'
                    }

                    category = 'unknown'
                    for prefix, cat in category_map.items():
                        if mime_type.startswith(prefix):
                            category = cat
                            break

                    is_permitted = any(mime_type.startswith(prefix) for prefix in allowed_prefixes)
                    error = None
        except Exception as e:
            mime_type = None
            category = 'unknown'
            is_permitted = False
            error = f"Processing error: {str(e)}"

        report.append({
            'file_path': normalized_path if 'normalized_path' in locals() else str(path),
            'mime_type': mime_type,
            'category': category,
            'is_permitted': is_permitted,
            'error': error
        })

    return report

