from datetime import date
from typing import List, Dict, Any, Optional
import logging

def process_transaction_dates(transaction_records: List[Dict[str, Any]], logger: Optional[logging.Logger] = None) -> Dict[str, List[date]]:
    if not transaction_records:
        return {}

    if logger is None:
        logger = logging.getLogger(__name__)

    monthly_transactions = {}
    valid_dates_count = 0
    invalid_dates_count = 0

    for record in transaction_records:
        if not isinstance(record, dict):
            logger.warning(f"Skipping non-dictionary record: {record}")
            invalid_dates_count += 1
            continue

        date_str = record.get('transaction_date')
        if not date_str or not isinstance(date_str, str):
            logger.debug(f"Missing or non-string date in record: {record}")
            invalid_dates_count += 1
            continue

        try:
            clean_date_str = date_str.split('T')[0].strip()
            if not clean_date_str:
                raise ValueError("Empty date string after cleaning")

            parsed_date = date.fromisoformat(clean_date_str)
            month_key = parsed_date.strftime('%Y-%m')

            if month_key not in monthly_transactions:
                monthly_transactions[month_key] = []
            monthly_transactions[month_key].append(parsed_date)
            valid_dates_count += 1

        except (ValueError, AttributeError) as e:
            logger.warning(f"Failed to parse date '{date_str}': {e}")
            invalid_dates_count += 1
            continue

    logger.info(f"Processed {valid_dates_count} valid dates, {invalid_dates_count} invalid dates")
    return monthly_transactions

