            raise TypeError("Each item in metrics_data must be a dictionary")

        required_keys = {"identifier", "computed", "expected"}
        if not required_keys.issubset(item.keys()):
            raise KeyError(f"Missing required keys in item: {item.get('identifier', 'unknown')}")

        identifier = item["identifier"]
        computed = item["computed"]
        expected = item["expected"]

        if not isinstance(identifier, str):
            raise TypeError("Identifier must be a string")

        if not isinstance(computed, (int, float)):
            raise TypeError(f"Computed value for '{identifier}' must be int or float, got {type(computed).__name__}")

        if not isinstance(expected, (int, float)):
            raise TypeError(f"Expected value for '{identifier}' must be int or float, got {type(expected).__name__}")

        try:
            test_case.assertAlmostEqual(computed, expected, delta=1e-6)
            passes += 1
        except AssertionError:
            failures += 1
            failed_identifiers.append(identifier)

    return {
        "total_comparisons": total,
        "passes": passes,
        "failures": failures,
        "failed_identifiers": failed_identifiers
    }

