import locale
import os
from typing import Optional

def process_multilingual_files(file_paths: list[str], use_environment_fallback: bool = False, common_fallbacks: list[str] = None) -> dict[str, tuple[str, str] | None]:
    if not isinstance(file_paths, list):
        raise TypeError("file_paths must be a list")

    if common_fallbacks is None:
        common_fallbacks = ['utf-8', 'latin-1', 'cp1252', 'iso-8859-1', 'ascii']

    result = {}
    preferred_encoding = locale.getpreferredencoding(False)

    if use_environment_fallback:
        env_encoding = os.environ.get('PYTHONIOENCODING', os.environ.get('LANG', '').split('.')[-1])
        if env_encoding and env_encoding.lower() != 'utf-8':
            encoding_priority = [env_encoding, preferred_encoding] + common_fallbacks
        else:
            encoding_priority = [preferred_encoding] + common_fallbacks
    else:
        encoding_priority = [preferred_encoding] + common_fallbacks

    for file_path in file_paths:
        if not isinstance(file_path, str):
            result[file_path] = None
            continue

        if not os.path.exists(file_path):
            result[file_path] = None
            continue

        content = None
        detected_encoding = None

        for encoding in encoding_priority:
            try:
                with open(file_path, 'r', encoding=encoding, errors='strict') as f:
                    content = f.read()
                    detected_encoding = encoding
                    break
            except (UnicodeDecodeError, LookupError, OSError):
                continue

        if content is not None:
            preview = content[:100] if len(content) >= 100 else content
            result[file_path] = (detected_encoding, preview)
        else:
            result[file_path] = None

    return result

