import datetime
import logging
from typing import Dict, List, Tuple

logging.basicConfig(level=logging.WARNING)

def summarize_milestones_by_iso_week(
    milestone_data: list[dict], 
    max_years_historical: int = 5
) -> dict[tuple[int, int], int]:
    if not isinstance(milestone_data, list):
        raise TypeError("milestone_data must be a list")

    summary = {}
    cutoff_date = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=365 * max_years_historical)

    for record in milestone_data:
        if not isinstance(record, dict):
            logging.warning(f"Skipping non-dictionary record: {record}")
            continue

        timestamp_str = record.get("timestamp")
        if not timestamp_str:
            logging.warning("Missing timestamp field in record")
            continue

        try:
            dt = datetime.datetime.fromisoformat(timestamp_str)
        except (ValueError, TypeError):
            logging.warning(f"Invalid timestamp format: {timestamp_str}")
            continue

        if dt.tzinfo is None:
            logging.warning(f"Missing timezone info for timestamp: {timestamp_str}")
            continue

        if dt > datetime.datetime.now(datetime.timezone.utc):
            logging.warning(f"Future timestamp ignored: {timestamp_str}")
            continue

        if dt < cutoff_date:
            continue

        iso_calendar = dt.isocalendar()
        iso_year, iso_week, iso_day = iso_calendar

        if iso_week >= 52:
            if dt.year != iso_year:
                logging.warning(f"Year-end transition week detected: {dt.date()} -> ISO {iso_year}-W{iso_week}")

        key = (iso_year, iso_week)
        summary[key] = summary.get(key, 0) + 1

    return summary

