from collections.abc import Sized, Iterable
import logging
from typing import Any, Callable

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def process_container_batch(containers, threshold: int, transform_func: Callable = lambda x: x) -> tuple[list, dict]:
    if not isinstance(threshold, int) or threshold < 0:
        raise ValueError("Threshold must be a non-negative integer")

    if not callable(transform_func):
        raise TypeError("transform_func must be callable")

    filtered_out = 0
    total_elements = 0
    results = []
    stats = {"filtered_containers": 0, "processed_elements": 0, "skipped_errors": 0}

    for i, container in enumerate(containers):
        try:
            size_check_failed = False

            if isinstance(container, Sized):
                size = len(container)
                if size == 0 or size < threshold:
                    filtered_out += 1
                    size_check_failed = True
            else:
                filtered_out += 1
                size_check_failed = True

            if not size_check_failed and isinstance(container, Iterable):
                try:
                    for element in container:
                        transformed = transform_func(element)
                        results.append(transformed)
                        total_elements += 1
                except Exception as e:
                    logger.warning(f"Error iterating container at index {i}: {type(e).__name__}")
                    stats["skipped_errors"] += 1
                    continue
        except Exception as e:
            logger.warning(f"Error processing container at index {i}: {type(e).__name__}")
            filtered_out += 1
            stats["skipped_errors"] += 1
            continue

    stats["filtered_containers"] = filtered_out
    stats["processed_elements"] = total_elements

    logger.info(f"Filtered out {filtered_out} containers, processed {total_elements} elements")
    return results, stats

