def log_calls(logger: logging.Logger) -> Callable:
    def decorator(func: Callable) -> Callable:
        @wraps(func)
        def wrapper(*args, **kwargs):
            logger.debug(f"Calling {func.__name__}", stacklevel=2)
            try:
                result = func(*args, **kwargs)
                logger.debug(f"Returning from {func.__name__}", stacklevel=2)
                return result
            except Exception as e:
