def decorate_with_logging(f: Callable[P, R]) -> Callable[P, R]:
    @functools.wraps(f)
    def wrapper(*args: P.args, **kwargs: P.kwargs) -> R:
        result = f(*args, **kwargs)
        wrapper.log_string = f'Called with args={args}, kwargs={kwargs}; returned={result}'
        return result
    return cast(Callable[P, R], wrapper)

