import pydantic
from typing import Tuple, Any, Dict, List

class DemoModel(pydantic.BaseModel):
    a: int
    b: str
    c: float = 3.14

    @pydantic.field_validator('a')
    @classmethod
    def validate_a(cls, v):
        if v < 0:
            raise ValueError('a must be non-negative')
        return v * 2

    @pydantic.field_validator('b')
    @classmethod
    def validate_b(cls, v):
        if not v.isalpha():
            raise ValueError('b must be alphabetic')
        return v.upper()

def compare_instantiation_methods(data: dict) -> tuple:
    # Standard instantiation — runs validators
    try:
        standard_instance = DemoModel(**data)
        standard_fields = standard_instance.model_dump()
        standard_validators_executed = {
            f: getattr(standard_instance, f) for f in ['a', 'b'] if f in data
        }
    except Exception:
        standard_fields = {}
        standard_validators_executed = {}

    # model_construct — bypasses validators, fill in defaults explicitly
    defaults = {f: info.default for f, info in DemoModel.model_fields.items()
                if info.default is not pydantic.fields.PydanticUndefined}
    construct_data = {**defaults, **data}
    construct_instance = DemoModel.model_construct(**construct_data)
    construct_fields = construct_instance.model_dump()
    construct_validators_executed = {f: v for f, v in data.items() if f in ['a', 'b']}

    # Type name mapping for all model fields
    standard_conversions = {f: info.annotation.__name__
                            for f, info in DemoModel.model_fields.items()}
    construct_conversions = standard_conversions.copy()

    return (
        standard_fields,
        construct_fields,
        standard_validators_executed,
        construct_validators_executed,
        standard_conversions,
        construct_conversions,
    )

