import logging
from fractions import gcd
from typing import Optional, List, Tuple

def process_gear_ratios(ratio_pairs: List[Tuple[int, int]], logger: Optional[logging.Logger] = None) -> Tuple[List[Tuple[int, int]], int]:
    if logger is None:
        logger = logging.getLogger(__name__)

    simplified_pairs = []
    first_terms = []

    for idx, (numerator, denominator) in enumerate(ratio_pairs):
        try:
            if not isinstance(numerator, int) or not isinstance(denominator, int):
                raise TypeError("Both ratio terms must be integers")

            if numerator <= 0 or denominator <= 0:
                raise ValueError("Both ratio terms must be positive integers")

            common_divisor = gcd(numerator, denominator)
            simplified_num = numerator // common_divisor
            simplified_den = denominator // common_divisor

            simplified_pairs.append((simplified_num, simplified_den))
            first_terms.append(simplified_num)

        except (TypeError, ValueError) as e:
            logger.warning(f"Skipping invalid pair at index {idx}: {e}")
            continue
        except Exception as e:
            logger.error(f"Unexpected error processing pair at index {idx}: {e}")
            continue

    if not first_terms:
        return simplified_pairs, 1

    base_gcd = first_terms[0]
    for term in first_terms[1:]:
        base_gcd = gcd(base_gcd, term)
        if base_gcd == 1:
            break

    return simplified_pairs, base_gcd

