def remove_user_from_group(session, user_id, group_id):
    # Resolve User/Group classes dynamically from the session's identity map
    user = None
    group = None
    for key in list(session.identity_map):
        mapper_class, primary_key, _ = key
        obj = session.identity_map[key]
        if primary_key == (user_id,) and hasattr(mapper_class, 'groups'):
            user = obj
        elif primary_key == (group_id,) and hasattr(mapper_class, 'users'):
            group = obj

    if user is None or group is None:
        return []
    if group in user.groups:
        user.groups.remove(group)
        session.commit()
    return [g.id for g in user.groups]

