import asyncio

def demonstrate_timeout_behavior(url: str) -> dict:
    """
    Demonstrates timeout behavior of httpx GET requests to a URL where the server
    takes 7 seconds to respond. Shows the difference between explicit timeout
    settings and default behavior (no timeout).

    Returns a dict with keys 'successful' and 'failed', each containing lists
    of request descriptions with their timeout settings and outcomes.
    """
    results = {'successful': [], 'failed': []}

    timeout_configs = [
        None,
        httpx.Timeout(None, connect=5.0),
        httpx.Timeout(10.0),
        httpx.Timeout(2.0),
        5.0
    ]

    for i, timeout in enumerate(timeout_configs):
        try:
            if timeout is None:
                response = httpx.request('GET', url, timeout=timeout)
            else:
                response = httpx.request('GET', url, timeout=timeout)

            if response.status_code == 200:
                results['successful'].append({
                    'request_id': i,
                    'timeout_setting': str(timeout),
                    'status': response.status_code,
                    'elapsed': response.elapsed.total_seconds()
                })
            else:
                results['failed'].append({
                    'request_id': i,
                    'timeout_setting': str(timeout),
                    'error': f'HTTP {response.status_code}'
                })
        except httpx.TimeoutException:
            results['failed'].append({
                'request_id': i,
                'timeout_setting': str(timeout),
                'error': 'Timeout'
            })
        except Exception as e:
            results['failed'].append({
                'request_id': i,
                'timeout_setting': str(timeout),
                'error': str(e)
            })

    return results

