import warnings

def deprecated_since(version):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(
                f"Function {func.__name__} is deprecated since version {version}.",
                category=DeprecationWarning,
                stacklevel=2
            )
            return func(*args, **kwargs)
        functools.update_wrapper(wrapper, func)
        wrapper.__wrapped__ = func
        return wrapper
    return decorator

