    created_at: ReadOnly[str]

def validate_preference_update(original: UserPreferences, updated: UserPreferences) -> bool:
    type_hints = get_type_hints(UserPreferences, include_extras=True)

    for field_name, field_type in type_hints.items():
        if hasattr(field_type, '__origin__') and field_type.__origin__ is ReadOnly:
            if original.get(field_name) != updated.get(field_name):
                return False

    return True

import time

def count_set_bits(limit):
    builtin_total = 0
    manual_total = 0

    for i in range(limit + 1):
        builtin_total += i.bit_count()

    for i in range(limit + 1):
        count = 0
        n = i
        while n:
            count += n & 1
            n >>= 1
        manual_total += count

    return (builtin_total, manual_total)

