from typing import Dict, Any
from solution import merge_configs
from unittest.mock import patch


def test_basic_merge():
    """Test basic dictionary merging."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {"a": 1, "b": 2}
        override1 = {"b": 3, "c": 4}
        override2 = {"c": 5, "d": 6}

        result = merge_configs(base, override1, override2)
        expected = {"a": 1, "b": 3, "c": 5, "d": 6}
        assert result == expected


def test_no_overrides():
    """Test merging with no override dictionaries."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {"x": 10, "y": 20}
        result = merge_configs(base)
        assert result == base
        # Ensure it's a copy, not the same object
        assert result is not base


def test_single_override():
    """Test merging with a single override."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {"key1": "value1", "key2": "value2"}
        override = {"key2": "new_value", "key3": "value3"}

        result = merge_configs(base, override)
        expected = {"key1": "value1", "key2": "new_value", "key3": "value3"}
        assert result == expected


def test_empty_dictionaries():
    """Test merging with empty dictionaries."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        # Empty base
        result1 = merge_configs({}, {"a": 1})
        assert result1 == {"a": 1}

        # Empty override
        result2 = merge_configs({"a": 1}, {})
        assert result2 == {"a": 1}

        # All empty
        result3 = merge_configs({}, {}, {})
        assert result3 == {}


def test_nested_dictionaries():
    """Test that nested dictionaries are overwritten, not merged recursively."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {"config": {"a": 1, "b": 2}, "other": "value"}
        override1 = {"config": {"b": 3, "c": 4}}
        override2 = {"config": {"c": 5}}

        result = merge_configs(base, override1, override2)
        expected = {"config": {"c": 5}, "other": "value"}
        assert result == expected


def test_multiple_overrides_order():
    """Test that later overrides take precedence."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {"a": 1, "b": 2}
        override1 = {"a": 10, "c": 30}
        override2 = {"a": 20, "b": 40}
        override3 = {"c": 50, "d": 60}

        result = merge_configs(base, override1, override2, override3)
        expected = {"a": 20, "b": 40, "c": 50, "d": 60}
        assert result == expected


def test_different_value_types():
    """Test merging dictionaries with various value types."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {"int": 1, "str": "hello", "list": [1, 2], "bool": True, "none": None}
        override = {"int": 2, "str": "world", "list": [3, 4], "bool": False}

        result = merge_configs(base, override)
        expected = {"int": 2, "str": "world", "list": [3, 4], "bool": False, "none": None}
        assert result == expected


def test_large_number_of_overrides():
    """Test merging with many override dictionaries."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {"initial": 0}
        overrides = [{f"key_{i}": i} for i in range(100)]

        result = merge_configs(base, *overrides)
        expected = {"initial": 0, **{f"key_{i}": i for i in range(100)}}
        assert result == expected


def test_copy_is_made():
    """Test that the base dictionary is copied, not modified in place."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {"original": "value"}
        override = {"new": "data"}

        result = merge_configs(base, override)
        # Modify the result
        result["modified"] = "yes"
        # Base should remain unchanged
        assert "modified" not in base
        assert base == {"original": "value"}


def test_non_string_keys():
    """Test merging dictionaries with non-string keys."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {1: "one", ("a", "b"): "tuple", 3.14: "pi"}
        override = {1: "ONE", ("a", "b"): "TUPLE", "new": "key"}

        result = merge_configs(base, override)
        expected = {1: "ONE", ("a", "b"): "TUPLE", 3.14: "pi", "new": "key"}
        assert result == expected


def test_override_with_none_values():
    """Test that None values in overrides properly override existing values."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {"a": 1, "b": 2, "c": 3}
        override = {"a": None, "b": None}

        result = merge_configs(base, override)
        expected = {"a": None, "b": None, "c": 3}
        assert result == expected


def test_function_annotation():
    """Test that the function has the correct type annotations."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        from inspect import signature
        sig = signature(merge_configs)

        # The annotation might be represented differently in different Python versions
        # We need to check for both possible representations
        base_annotation = str(sig.parameters['base'].annotation)
        return_annotation = str(sig.return_annotation)

        # Accept both "Dict[Any, Any]" and "typing.Dict[typing.Any, typing.Any]"
        assert base_annotation in ["Dict[Any, Any]", "typing.Dict[typing.Any, typing.Any]"]
        assert return_annotation in ["Dict[Any, Any]", "typing.Dict[typing.Any, typing.Any]"]


def test_mixed_key_types_across_overrides():
    """Test merging with different key types across base and overrides."""
    with patch('solution.unittest.mock.__version__', '1.0', create=True):
        base = {1: "int_key", "2": "str_key"}
