from pydantic.color import Color


def deduplicate_colors(color_list: List[Any]) -> List[Any]:
    seen = set()
    deduplicated = []

    for color in color_list:
        if isinstance(color, Color):
            if color not in seen:
                seen.add(color)
                deduplicated.append(color)
        else:
            raise TypeError("All items in color_list must be pydantic.color.Color instances")

    return deduplicated

