import inspect
from typing import List, Dict, Any
from pydantic.utils import is_valid_field

def inspect_class_fields(cls: type, include_parents: bool = False) -> Dict[str, List[str]]:
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class type, got {type(cls).__name__}")

    valid_fields = []
    internal_attrs = []

    members = inspect.getmembers(cls)
    if include_parents:
        for base in cls.__bases__:
            members.extend(inspect.getmembers(base))

    for name, value in members:
        if callable(value):
            continue

        if name.startswith('_'):
            internal_attrs.append(name)
            continue

        try:
            if is_valid_field(name):
                valid_fields.append(name)
            else:
                internal_attrs.append(name)
        except Exception as e:
            internal_attrs.append(name)

    valid_fields = sorted(list(set(valid_fields)))
    internal_attrs = sorted(list(set(internal_attrs)))

    return {
        'valid_fields': valid_fields,
        'internal_attrs': internal_attrs
    }

