import calendar
import logging

logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

def february_summary_report(years: list, start_year: int = None, end_year: int = None) -> dict:
    if not isinstance(years, list):
        logger.warning(f"Input must be a list, got {type(years).__name__}")
        return {"error": "Invalid input type"}

    valid_years = []
    leap_years = []
    total_days = 0

    for year in years:
        if not isinstance(year, int) or year < 1 or year > 9999:
            logger.warning(f"Skipping invalid year: {year}")
            continue

        if start_year is not None and year < start_year:
            continue
        if end_year is not None and year > end_year:
            continue

        try:
            feb_days = calendar.monthrange(year, calendar.February)[1]
            total_days += feb_days
            valid_years.append(year)
            if feb_days == 29:
                leap_years.append(year)
        except (ValueError, TypeError) as e:
            logger.warning(f"Error processing year {year}: {e}")
            continue

    if not valid_years:
        return {
            "total_february_days": 0,
            "average_february_days": 0.0,
            "leap_years": [],
            "years_processed": 0
        }

    avg_days = total_days / len(valid_years)

    return {
        "total_february_days": total_days,
        "average_february_days": round(avg_days, 2),
        "leap_years": sorted(leap_years),
        "years_processed": len(valid_years)
    }

import time
import math

def analyze_benchmark(benchmark_results: list[float]) -> dict[str, float|int]:
    n = len(benchmark_results)
    if n == 0:
        return {"average": 0.0, "std_dev": 0.0, "slow_count": 0}

    total = sum(benchmark_results)
    average = total / n

    variance = sum((x - average) ** 2 for x in benchmark_results) / n
    std_dev = math.sqrt(variance)

    slow_count = sum(1 for x in benchmark_results if x > 0.020)

    time.sleep(0.0)

    return {"average": average, "std_dev": std_dev, "slow_count": slow_count}

import pandas as pd

def generate_targeted_promotion_matrix(products_df: pd.DataFrame, customers_df: pd.DataFrame) -> pd.DataFrame:
    if products_df.empty or customers_df.empty:
        raise ValueError("Input DataFrames cannot be empty")

    if 'discount_tier' not in products_df.columns or 'loyalty_level' not in customers_df.columns:
        raise KeyError("Required columns missing from input DataFrames")

    filtered_products = products_df[products_df['discount_tier'] != 'NONE'].copy()
    filtered_customers = customers_df[customers_df['loyalty_level'].isin(['SILVER', 'GOLD', 'PLATINUM'])].copy()

    if filtered_products.empty or filtered_customers.empty:
        return pd.DataFrame(columns=['campaign_id'])

    merged_df = filtered_products.merge(filtered_customers, how='cross')

    if 'sku' not in merged_df.columns or 'profile_id' not in merged_df.columns:
        raise KeyError("Required columns for campaign_id calculation not found")

    merged_df['campaign_id'] = merged_df['sku'].astype(str) + '-' + merged_df['profile_id'].astype(str)

    result_df = merged_df.sort_values('campaign_id', ascending=True)

    return result_df.reset_index(drop=True)

import pandas as pd
import numpy as np

def prepare_account_summary(df: pd.DataFrame, account_col: str, value_col: str) -> pd.DataFrame:
    if df.empty:
        raise ValueError("Input DataFrame cannot be empty")

    required_cols = {account_col, value_col}
    if not required_cols.issubset(df.columns):
        missing = required_cols - set(df.columns)
        raise KeyError(f"Missing required columns: {missing}")

    if not pd.api.types.is_numeric_dtype(df[value_col]):
        raise TypeError(f"Column '{value_col}' must contain numeric data")

    df_clean = df.copy()
    df_clean[account_col] = df_clean[account_col].astype('category')

    mask = df_clean[value_col].notna() & (df_clean[value_col] != 0)
    df_filtered = df_clean.loc[mask].reset_index(drop=True)

    if df_filtered.empty:
        return pd.DataFrame(columns=[account_col, 'average_value'])

    try:
        pivot_result = df_filtered.pivot_table(
            index=account_col,
            values=value_col,
            aggfunc='mean',
            observed=True
        )
    except Exception as e:
        raise RuntimeError(f"Pivot table operation failed: {str(e)}")

    pivot_result.columns = ['average_value']
    pivot_result['average_value'] = pivot_result['average_value'].round(2)

    summary = pivot_result.sort_values('average_value', ascending=False)
    return summary.reset_index()

