import calendar
from typing import Union

def normalize_month(month_identifier: Union[str, int], locale: str = "en_US") -> int:
    if isinstance(month_identifier, int):
        if 1 <= month_identifier <= 12:
            return month_identifier
        raise ValueError(f"Month number must be between 1 and 12, got {month_identifier}")

    month_str = str(month_identifier).strip().lower()

    if month_str.isdigit():
        month_num = int(month_str)
        if 1 <= month_num <= 12:
            return month_num
        raise ValueError(f"Month number must be between 1 and 12, got {month_num}")

    month_names = {}
    for month_idx in range(calendar.JANUARY, calendar.JANUARY + 12):
        month_names[calendar.month_name[month_idx].lower()] = month_idx
        month_names[calendar.month_abbr[month_idx].lower()] = month_idx

    if month_str in month_names:
        return month_names[month_str]

    raise ValueError(f"Invalid month identifier: {month_identifier}")

def device_with_most_active_bits(device_ids: list[int]) -> int:
    if not device_ids:
        raise ValueError("device_ids list cannot be empty")

    max_bits = -1
    result_device = None

    for device_id in device_ids:
        bit_count = device_id.bit_count()
        if bit_count > max_bits:
            max_bits = bit_count
            result_device = device_id

    return result_device

