import datetime
import logging
from typing import Union

logging.basicConfig(level=logging.WARNING)

def process_log_entries(raw_entries: list, current_system_time: float | None = None) -> list[dict[str, Union[str, datetime.datetime]]]:
    if not isinstance(raw_entries, list):
        raise TypeError("raw_entries must be a list")

    if current_system_time is None:
        current_system_time = datetime.datetime.now().timestamp()
    elif not isinstance(current_system_time, (int, float)):
        raise TypeError("current_system_time must be numeric or None")

    processed_entries = []
    valid_severities = {'ERROR', 'WARNING'}

    for idx, entry in enumerate(raw_entries):
        if not isinstance(entry, tuple) or len(entry) != 2:
            logging.warning(f"Skipping malformed entry at index {idx}: not a 2-element tuple")
            continue

        timestamp, severity = entry

        if not isinstance(timestamp, (int, float)):
            logging.warning(f"Skipping entry at index {idx}: invalid timestamp type")
            continue

        if not isinstance(severity, str):
            logging.warning(f"Skipping entry at index {idx}: severity must be string")
            continue

        if timestamp > current_system_time:
            continue

        if severity not in valid_severities:
            continue

        try:
            local_dt = datetime.datetime.fromtimestamp(timestamp)
        except (ValueError, OSError) as e:
            logging.warning(f"Skipping entry at index {idx}: timestamp conversion failed: {e}")
            continue

        processed_entries.append({
            'severity': severity,
            'timestamp': local_dt
        })

    return processed_entries

