import ipaddress
from typing import Dict, List, Tuple

def normalize_ip_addresses(ip_list: List[str], log_errors: bool = True) -> Tuple[Dict[str, str], List[str]]:
    normalized_map = {}
    error_log = []

    if not isinstance(ip_list, list):
        if log_errors:
            error_log.append(f"Input must be a list, got {type(ip_list).__name__}")
        return normalized_map, error_log

    for original_ip in ip_list:
        if not isinstance(original_ip, str):
            if log_errors:
                error_log.append(f"IP must be string, got {type(original_ip).__name__}: {original_ip}")
            continue

        ip_str = original_ip.strip()
        if not ip_str:
            if log_errors:
                error_log.append(f"Empty IP string encountered")
            continue

        try:
            ip_obj = ipaddress.ip_address(ip_str)

            if isinstance(ip_obj, ipaddress.IPv4Address):
                normalized_ip = str(ip_obj.ipv6_mapped)
            elif isinstance(ip_obj, ipaddress.IPv6Address):
                normalized_ip = str(ip_obj.compressed)
            else:
                if log_errors:
                    error_log.append(f"Unknown IP type for: {ip_str}")
                continue

            normalized_map[original_ip] = normalized_ip

        except (ValueError, ipaddress.AddressValueError) as e:
            if log_errors:
                error_log.append(f"Invalid IP address '{ip_str}': {str(e)}")
            continue
        except Exception as e:
            if log_errors:
                error_log.append(f"Unexpected error processing '{ip_str}': {str(e)}")
            continue

    return normalized_map, error_log

import numpy as np

def matrix_power(matrix: np.ndarray, exponent: int) -> np.ndarray:
    if exponent == 0:
        return np.identity(matrix.shape[0], dtype=matrix.dtype)
    elif exponent < 0:
        matrix = np.linalg.inv(matrix)
        exponent = -exponent

    result = np.identity(matrix.shape[0], dtype=matrix.dtype)
    base = matrix.copy()

    while exponent > 0:
        if exponent % 2 == 1:
            result = np.dot(result, base)
        base = np.dot(base, base)
        exponent //= 2

    return result

import pandas as pd
import logging
from typing import Optional

def analyze_weekly_ticket_volume(timestamp_series: pd.Series, start_date: pd.Timestamp, end_date: pd.Timestamp, logger: Optional[logging.Logger] = None) -> pd.DataFrame:
    if not isinstance(timestamp_series, pd.Series):
        raise TypeError("timestamp_series must be a pandas Series")
    if not isinstance(start_date, pd.Timestamp) or not isinstance(end_date, pd.Timestamp):
        raise TypeError("start_date and end_date must be pandas Timestamps")
    if start_date > end_date:
        raise ValueError("start_date must be before or equal to end_date")

    original_count = len(timestamp_series)
    valid_mask = timestamp_series.notna()
    if valid_mask.sum() < original_count:
        skipped_count = original_count - valid_mask.sum()
        warning_msg = f"Skipped {skipped_count} malformed or missing timestamps"
        if logger:
            logger.warning(warning_msg)
        else:
            print(f"WARNING: {warning_msg}")

    filtered_series = timestamp_series[valid_mask]
    date_range_mask = (filtered_series >= start_date) & (filtered_series <= end_date)
    filtered_series = filtered_series[date_range_mask]

    if len(filtered_series) == 0:
        return pd.DataFrame(columns=['ISO_year', 'ISO_week', 'ticket_count'])

    iso_calendar_df = filtered_series.dt.isocalendar()
    iso_calendar_df = iso_calendar_df.rename(columns={'year': 'ISO_year', 'week': 'ISO_week'})

    weekly_counts = iso_calendar_df.groupby(['ISO_year', 'ISO_week']).size().reset_index(name='ticket_count')
    weekly_counts = weekly_counts.sort_values(['ISO_year', 'ISO_week']).reset_index(drop=True)

    return weekly_counts

