import re
import logging
from typing import Dict, List

def process_pattern_batch(patterns: List[str], input_strings: List[str], logger: logging.Logger) -> Dict[str, List[str]]:
    if not isinstance(patterns, list) or not isinstance(input_strings, list):
        logger.error("Patterns and input_strings must be lists")
        return {}

    if not all(isinstance(p, str) for p in patterns):
        logger.error("All patterns must be strings")
        return {}

    if not all(isinstance(s, str) for s in input_strings):
        logger.error("All input strings must be strings")
        return {}

    compiled_patterns = {}
    compilation_errors = []

    for pattern in patterns:
        try:
            compiled = re.compile(pattern)
            compiled_patterns[pattern] = compiled
        except re.PatternError as e:
            compilation_errors.append((pattern, str(e)))
            logger.warning(f"Pattern compilation failed for '{pattern}': {e}")

    if compilation_errors:
        logger.info(f"Failed to compile {len(compilation_errors)} patterns out of {len(patterns)}")

    results = {pattern: [] for pattern in compiled_patterns.keys()}

    for input_str in input_strings:
        for pattern_str, compiled_pattern in compiled_patterns.items():
            if compiled_pattern.search(input_str):
                results[pattern_str].append(input_str)

    for pattern_str, matches in results.items():
        if matches:
            logger.debug(f"Pattern '{pattern_str}' matched {len(matches)} strings")

    return results

