def test_solution():
    # Test case 1: Normal case with multiple sublists
    assert find_common_gcd([[12, 18, 24], [45, 30], [7, 14, 21, 28]]) == {0: 6, 1: 15, 2: 7}

    # Test case 2: Edge case with empty sublist
    assert find_common_gcd([[], [5, 10], [8]]) == {0: 0, 1: 5, 2: 8}

    # Test case 3: Edge case with single element sublists and negative numbers
    assert find_common_gcd([[7], [-14, 21], [0, 5], [0]]) == {0: 7, 1: 7, 2: 5, 3: 0}

    # Verify math.gcd is used correctly by checking behavior with pairwise calls
    # This indirectly tests the API usage
    test_sublist = [12, 18, 24]
    expected_gcd = math.gcd(math.gcd(12, 18), 24)
    assert find_common_gcd([test_sublist]) == {0: expected_gcd}

