import datetime
from typing import Union, Tuple

def check_resolution_behavior(iterations: int, test_type: str) -> Union[bool, Tuple[int, int]]:
    if test_type == 'identity':
        first = datetime.timedelta.resolution
        for _ in range(iterations - 1):
            if datetime.timedelta.resolution is not first:
                return False
        return True
    elif test_type == 'memory':
        seen = {}
        for _ in range(iterations):
            obj = datetime.timedelta.resolution
            seen[id(obj)] = obj
        total_memory = sum(sys.getsizeof(obj) for obj in seen.values())
        return (len(seen), total_memory)
    else:
        raise ValueError("test_type must be 'identity' or 'memory'")

