def process_concurrent_requests(urls: list[str], timeout: float) -> dict[str, bytes | Exception]:
    async def _process() -> Dict[str, bytes | Exception]:
        async with aiohttp.ClientSession() as session:
            tasks = {url: asyncio.create_task(fetch_url(session, url, timeout)) for url in urls}
            results = {}
            for url, task in tasks.items():
                try:
                    results[url] = await task
                except Exception as e:
                    results[url] = e
            return results

    return asyncio.run(_process())

