from typing import Dict, Any
from collections.abc import Mapping
from solution import merge_configs


def test_normal_merge_no_overlap():
    """Test merging dictionaries with no overlapping keys."""
    base = {"a": 1, "b": 2}
    override = {"c": 3, "d": 4}
    result = merge_configs(base, override)
    expected = {"a": 1, "b": 2, "c": 3, "d": 4}
    assert result == expected
    # Ensure original dictionaries are not modified
    assert base == {"a": 1, "b": 2}
    assert override == {"c": 3, "d": 4}


def test_normal_merge_with_overlap():
    """Test merging dictionaries with overlapping keys."""
    base = {"a": 1, "b": 2, "c": 3}
    override = {"b": 20, "c": 30, "d": 40}
    result = merge_configs(base, override)
    expected = {"a": 1, "b": 20, "c": 30, "d": 40}
    assert result == expected


def test_override_completely_overwrites():
    """Test when override dictionary completely overwrites base keys."""
    base = {"x": 100, "y": 200}
    override = {"x": 1000, "y": 2000}
    result = merge_configs(base, override)
    expected = {"x": 1000, "y": 2000}
    assert result == expected


