        logger = logging.getLogger()
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            logger.info(f"Entering {func.__name__}", stacklevel=2)
            try:
                result = func(*args, **kwargs)
                logger.info(f"Exiting {func.__name__}", stacklevel=2)
