def test_solution():
    # Test case 1: use_posix_spawn=False (default)
    # Ensure the flag is not set when not requested
    if hasattr(subprocess, '_USE_POSIX_SPAWN'):
        original_flag = subprocess._USE_POSIX_SPAWN
    else:
        original_flag = None

    proc = spawn_process_with_flag(['echo', 'test'])
    assert isinstance(proc, subprocess.Popen)
    proc.wait()
    if original_flag is not None:
        assert subprocess._USE_POSIX_SPAWN == original_flag
    else:
        assert not hasattr(subprocess, '_USE_POSIX_SPAWN')

    # Test case 2: use_posix_spawn=True
    # Verify the flag is set before Popen creation
    proc = spawn_process_with_flag(['echo', 'test2'], use_posix_spawn=True)
    assert isinstance(proc, subprocess.Popen)
    proc.wait()
    # Check that the flag was set (only in Python 3.13+)
    if hasattr(subprocess, '_USE_POSIX_SPAWN'):
        assert subprocess._USE_POSIX_SPAWN is True
    # Clean up: restore original flag if it existed
    if original_flag is not None:
        subprocess._USE_POSIX_SPAWN = original_flag
    else:
        if hasattr(subprocess, '_USE_POSIX_SPAWN'):
            del subprocess._USE_POSIX_SPAWN

    # Test case 3: use_posix_spawn=True with empty command list (edge case)
    # Should raise an exception, but we verify flag is set before that
    try:
        spawn_process_with_flag([], use_posix_spawn=True)
    except Exception:
        pass
    # Ensure flag was set even if Popen fails
    if hasattr(subprocess, '_USE_POSIX_SPAWN'):
        assert subprocess._USE_POSIX_SPAWN is True
    # Clean up again
    if original_flag is not None:
