import dbm

def create_and_verify_dbm(temp_filename: str) -> tuple[int, bool]:
    data = {"apple": 42, "banana": 17, "cherry": 99}

    with dbm.open(temp_filename, 'n') as db:
        for key, value in data.items():
            db[key] = str(value).encode()

    with dbm.open(temp_filename, 'r') as db:
        total_keys_retrieved = 0
        verification_success = True

        for key, expected_value in data.items():
            if key in db:
                retrieved = db[key].decode()
                if retrieved == str(expected_value):
                    total_keys_retrieved += 1
                else:
                    verification_success = False
            else:
                verification_success = False

        if len(data) != total_keys_retrieved:
            verification_success = False

    return total_keys_retrieved, verification_success

from sqlalchemy.sql.expression import select

def build_query(model, columns=None, **filters):
    if columns is None:
        columns = [model]
    else:
        columns = list(columns)
    query = select(*columns)
    if filters:
        conditions = []
        for key, value in filters.items():
            column = getattr(model, key)
            conditions.append(column == value)
        query = query.where(*conditions)
    return query

