from pathlib import Path

def generate_archive_inventory(root_path, allowed_extensions=None, exclude_dirs=None):
    root = Path(root_path)
    inventory = {}
    exclude_set = set(exclude_dirs) if exclude_dirs else set()

    for dirpath, dirnames, filenames in root.walk(top_down=True):
        current_dir = Path(dirpath)

        if exclude_dirs:
            dirnames[:] = [d for d in dirnames if d not in exclude_set]

        for filename in filenames:
            file_path = current_dir / filename

            if allowed_extensions:
                if file_path.suffix.lower() not in allowed_extensions:
                    continue

            relative_path = file_path.relative_to(root)
            inventory[str(relative_path)] = {
                'full_path': str(file_path.resolve()),
                'parent_dir': str(current_dir.relative_to(root)),
                'filename': filename,
                'extension': file_path.suffix.lower()
            }

    return inventory

