import logging

def formatTime(record, datefmt=None, style='%'):
    if style == '%':
        return logging.Formatter.formatTime(logging.Formatter(), record, datefmt)
    elif style == '{':
        if datefmt is None:
            datefmt = '{asctime}'
        formatted = logging.Formatter.formatTime(logging.Formatter(), record, datefmt.replace('{', '%').replace('}', ''))
        return formatted
    elif style == '$':
        if datefmt is None:
            datefmt = '$asctime'
        formatted = logging.Formatter.formatTime(logging.Formatter(), record, datefmt.replace('$', '%'))
        return formatted
    else:
        raise ValueError(f"Unsupported style: {style}")

