import logging
import logging.handlers
import queue


class AsyncQueueHandler(logging.handlers.QueueHandler):
    def __init__(self, queue, max_queue_size=None, **kwargs):
        super().__init__(queue)
        self.max_queue_size = max_queue_size
        self._warned = False

    def enqueue(self, record):
        if self.max_queue_size is not None:
            current_size = self.queue.qsize()
            threshold = int(self.max_queue_size * 0.9)
            if current_size >= threshold and not self._warned:
                logger = logging.getLogger()
                if logger.isEnabledFor(logging.WARNING):
                    logger.warning(
                        f"AsyncQueueHandler queue is at {current_size}/{self.max_queue_size} "
                        f"({current_size/self.max_queue_size:.0%}) capacity"
                    )
                self._warned = True
            elif current_size < threshold:
                self._warned = False
        super().enqueue(record)


def configure_async_logging():
    log_queue = queue.Queue(maxsize=1000)
    handler = AsyncQueueHandler(log_queue, max_queue_size=1000)
    listener = logging.handlers.QueueListener(
        log_queue, *logging.root.handlers, respect_handler_level=True
    )
    listener.start()
    return handler, listener

import math

def max_manhattan_distance(points: list[tuple[float, float]], reference: tuple[float, float]) -> float:
    if not points:
        return -math.inf

    ref_x, ref_y = reference
    max_distance = -math.inf

    for x, y in points:
        distance = abs(x - ref_x) + abs(y - ref_y)
        if distance > max_distance:
            max_distance = distance

    return max_distance

