            b_slice = treatment_b_data[:, t, m]

            a_valid = a_slice[~np.isnan(a_slice)]
            b_valid = b_slice[~np.isnan(b_slice)]

            if len(a_valid) == 0 or len(b_valid) == 0:
                continue

            try:
                stat, p_value = ranksums(
                    a_valid, 
                    b_valid, 
                    alternative='less', 
                    axis=0, 
                    nan_policy='omit'
                )
                results[t, m] = p_value
            except Exception:
                continue

    return results

