from torch.distributions.constraints import Constraint, positive, interval

def test_solution():
    # Test case 1: check_constraints=True with valid parameters
    parameters = {
        'scale': torch.tensor([1.0, 2.0, 3.0]),
        'loc': torch.tensor([-0.5, 0.0, 0.5])
    }
    constraints = {
        'scale': positive,
        'loc': interval(-1.0, 1.0)
    }
    result = validate_parameters(parameters, constraints, check_constraints=True)
    assert isinstance(result, dict)
    assert set(result.keys()) == {'scale', 'loc'}
    assert torch.all(result['scale']).item() is True
    assert torch.all(result['loc']).item() is True

    # Test case 2: check_constraints=True with invalid parameters
    parameters = {
        'scale': torch.tensor([-1.0, 2.0]),
        'loc': torch.tensor([-2.0, 2.0])
    }
    constraints = {
        'scale': positive,
        'loc': interval(-1.0, 1.0)
    }
    result = validate_parameters(parameters, constraints, check_constraints=True)
    assert isinstance(result, dict)
    assert torch.all(result['scale'] == torch.tensor([False, True])).item() is True
    assert torch.all(result['loc'] == torch.tensor([False, False])).item() is True

    # Test case 3: check_constraints=False
    parameters = {
        'scale': torch.tensor([-1.0, 2.0]),
        'loc': torch.tensor([-2.0, 2.0])
    }
    constraints = {
        'scale': positive,
        'loc': interval(-1.0, 1.0)
    }
    result = validate_parameters(parameters, constraints, check_constraints=False)
    assert isinstance(result, dict)
    for key in parameters:
        assert torch.all(result[key]).item() is True
        assert result[key].dtype == torch.bool

    # Test case 4: empty parameters dictionary
    parameters = {}
    constraints = {}
    result = validate_parameters(parameters, constraints, check_constraints=True)
    assert result == {}

    # Test case 5: verify Constraint.check is called correctly
    class MockConstraint(Constraint):
        def check(self, value):
            # Mock check that returns a tensor with alternating True/False
            return torch.tensor([True, False])

    mock_constraint = MockConstraint()
    parameters = {'param': torch.tensor([1.0, 2.0])}
    constraints = {'param': mock_constraint}
    result = validate_parameters(parameters, constraints, check_constraints=True)
    assert torch.all(result['param'] == torch.tensor([True, False])).item() is True

