def check_dropout_behavior(input_tensor, dropout_prob=0.5):
    class SimpleNet(nn.Module):
        def __init__(self, dropout_prob):
            super().__init__()
            self.dropout = nn.Dropout(p=dropout_prob)

        def forward(self, x):
            return self.dropout(x)

    model = SimpleNet(dropout_prob)
    model.eval()

    outputs = []
    for _ in range(10):
        with torch.no_grad():
            output = model(input_tensor)
            outputs.append(output)

    first_output = outputs[0]
    all_same = all(torch.equal(first_output, out) for out in outputs[1:])

    return all_same

