            for elem in root.iter():
                if elem.tag.endswith("}Description"):
                    orientation = elem.attrib.get(
                        "{http://ns.adobe.com/tiff/1.0/}Orientation"
                    )
                    if orientation:
                        self._exif[0x0112] = int(orientation)
                    break

    return self._exif

