from collections import Counter

def compute_inventory_change(previous_counts: dict[str, int], current_counts: dict[str, int]) -> dict[str, int]:
    previous_counter = Counter(previous_counts)
    current_counter = Counter(current_counts)
    net_change = current_counter.__sub__(previous_counter)
    return dict(net_change)

