import pytest
from typing import Dict
from solution import compute_inventory_change


def test_normal_case_positive_changes():
    """Test normal case with positive inventory changes."""
    previous = {"apple": 10, "banana": 5, "orange": 3}
    current = {"apple": 15, "banana": 8, "orange": 3}
    expected = {"apple": 5, "banana": 3}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_normal_case_negative_changes():
    """Test normal case with negative inventory changes."""
    previous = {"apple": 10, "banana": 5, "orange": 3}
    current = {"apple": 7, "banana": 2, "orange": 3}
    # Counter.__sub__ only keeps positive results, so negative changes are excluded
    expected: Dict[str, int] = {}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_mixed_changes():
    """Test case with both positive and negative changes."""
    previous = {"apple": 10, "banana": 5, "orange": 3, "grape": 8}
    current = {"apple": 12, "banana": 3, "orange": 5, "grape": 8}
    # Only positive changes are kept: apple (+2), orange (+2)
    expected = {"apple": 2, "orange": 2}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_new_items_added():
    """Test when new items are added to inventory."""
    previous = {"apple": 10, "banana": 5}
    current = {"apple": 10, "banana": 5, "orange": 3, "grape": 7}
    expected = {"orange": 3, "grape": 7}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_items_removed():
    """Test when items are completely removed from inventory."""
    previous = {"apple": 10, "banana": 5, "orange": 3}
    current = {"apple": 10, "banana": 5}
    # Removing items creates negative changes, which are excluded
    expected: Dict[str, int] = {}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_empty_previous_counts():
    """Test when previous counts is empty."""
    previous: Dict[str, int] = {}
    current = {"apple": 10, "banana": 5, "orange": 3}
    expected = {"apple": 10, "banana": 5, "orange": 3}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_empty_current_counts():
    """Test when current counts is empty."""
    previous = {"apple": 10, "banana": 5, "orange": 3}
    current: Dict[str, int] = {}
    # All changes are negative, so they are excluded
    expected: Dict[str, int] = {}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_both_empty():
    """Test when both previous and current counts are empty."""
    previous: Dict[str, int] = {}
    current: Dict[str, int] = {}
    expected: Dict[str, int] = {}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_zero_counts_preserved():
    """Test that items with zero net change are excluded from result."""
    previous = {"apple": 10, "banana": 5, "orange": 3}
    current = {"apple": 10, "banana": 5, "orange": 3}
    expected: Dict[str, int] = {}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_negative_counts_in_input():
    """Test handling of negative counts in input (edge case)."""
    previous = {"apple": -5, "banana": 3}
    current = {"apple": -2, "banana": 1}
    # apple: -2 - (-5) = 3 (positive, kept)
    # banana: 1 - 3 = -2 (negative, excluded)
    expected = {"apple": 3}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_large_numbers():
    """Test with large numbers to ensure no overflow issues."""
    previous = {"item1": 1000000, "item2": 500000}
    current = {"item1": 1000500, "item2": 499500}
    # item1: 1000500 - 1000000 = 500 (positive, kept)
    # item2: 499500 - 500000 = -500 (negative, excluded)
    expected = {"item1": 500}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_duplicate_items_same_counts():
    """Test that duplicate items with same counts work correctly."""
    # Note: In Python dicts, duplicate keys are not allowed.
    # The last value for a key wins, so previous["apple"] = 5
    previous = {"apple": 10, "apple": 5, "banana": 3}  # Last duplicate wins
    current = {"apple": 8, "banana": 3}
    expected = {"apple": 3}  # 8 - 5 = 3
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_case_sensitive_keys():
    """Test that keys are case-sensitive."""
    previous = {"Apple": 10, "apple": 5, "BANANA": 3}
    current = {"Apple": 8, "apple": 7, "banana": 2}
    # Apple: 8 - 10 = -2 (negative, excluded)
    # apple: 7 - 5 = 2 (positive, kept)
    # BANANA: 0 - 3 = -3 (negative, excluded) - not in current
    # banana: 2 - 0 = 2 (positive, kept) - not in previous
    expected = {"apple": 2, "banana": 2}
    result = compute_inventory_change(previous, current)
    assert result == expected


def test_result_is_plain_dict():
    """Test that result is a plain dict, not a Counter."""
    previous = {"apple": 10, "banana": 5}
    current = {"apple": 12, "banana": 3}
    result = compute_inventory_change(previous, current)
    assert isinstance(result, dict)
    assert not hasattr(result, "most_common")  # Not a Counter
    assert type(result) == dict


def test_immutability_of_input():
    """Test that input dictionaries are not modified."""
    previous = {"apple": 10, "banana": 5}
    current = {"apple": 12, "banana": 3}
    previous_copy = previous.copy()
    current_copy = current.copy()

    compute_inventory_change(previous, current)

    assert previous == previous_copy
    assert current == current_copy


def test_with_special_characters_in_keys():
    """Test with special characters in item names."""
    previous = {"item-1": 10, "item_2": 5, "item 3": 3}
    current = {"item-1": 8, "item_2": 7, "item 3": 3}
    # item-1: 8 - 10 = -2 (negative, excluded)
    # item_2: 7 - 5 = 2 (positive, kept)
    # item 3: 3 - 3 = 0 (excluded)
    expected = {"item_2": 2}
    result = compute_inventory_change(previous, current)
    assert result == expected

