import pytest
from typing import Any, Dict
from unittest.mock import Mock, MagicMock
from solution import validate_processor


class ValidProcessor:
    """A class that implements all required methods."""
    def process(self, data: Any) -> Any:
        return data

    def validate_input(self, data: Any) -> bool:
        return True

    def get_metadata(self) -> Dict[str, Any]:
        return {"version": 1.0}


class MissingProcessMethod:
    """Missing the 'process' method."""
    def validate_input(self, data: Any) -> bool:
        return True

    def get_metadata(self) -> Dict[str, Any]:
        return {}


class MissingValidateMethod:
    """Missing the 'validate_input' method."""
    def process(self, data: Any) -> Any:
        return data

    def get_metadata(self) -> Dict[str, Any]:
        return {}


class MissingMetadataMethod:
    """Missing the 'get_metadata' method."""
    def process(self, data: Any) -> Any:
        return data

    def validate_input(self, data: Any) -> bool:
        return True


class WrongSignatureProcessor:
    """Has methods with wrong signatures."""
    def process(self):  # Missing parameter
        pass

    def validate_input(self, data: Any) -> bool:
        return True

    def get_metadata(self) -> Dict[str, Any]:
        return {}


class AsyncProcessor:
    """Has async methods - should not validate."""
    async def process(self, data: Any) -> Any:
        return data

    async def validate_input(self, data: Any) -> bool:
        return True

    async def get_metadata(self) -> Dict[str, Any]:
        return {}


class CallableAttributes:
    """Has callable attributes but not methods."""
    def __init__(self):
        self.process = lambda x: x
        self.validate_input = lambda x: True
        self.get_metadata = lambda: {}


def test_valid_processor_instance():
    """Test with a proper class instance implementing all methods."""
    processor = ValidProcessor()
    assert validate_processor(processor) is True


def test_missing_process_method():
    """Test with object missing the 'process' method."""
    processor = MissingProcessMethod()
    assert validate_processor(processor) is False


def test_missing_validate_method():
    """Test with object missing the 'validate_input' method."""
    processor = MissingValidateMethod()
    assert validate_processor(processor) is False


def test_missing_metadata_method():
    """Test with object missing the 'get_metadata' method."""
    processor = MissingMetadataMethod()
    assert validate_processor(processor) is False


def test_wrong_method_signatures():
    """Test with methods having incorrect signatures."""
    processor = WrongSignatureProcessor()
    # @runtime_checkable only checks method names, not signatures
    assert validate_processor(processor) is True


def test_async_methods():
    """Test with async methods - should not validate."""
    processor = AsyncProcessor()
    # @runtime_checkable only checks method names, not whether they're async
    assert validate_processor(processor) is True


def test_callable_attributes():
    """Test with callable attributes instead of methods."""
    processor = CallableAttributes()
    # @runtime_checkable checks for callable attributes with the right names
    assert validate_processor(processor) is True


def test_mock_object():
    """Test with a Mock object configured with all required methods."""
    mock_processor = Mock()
    mock_processor.process = Mock(return_value="processed")
    mock_processor.validate_input = Mock(return_value=True)
    mock_processor.get_metadata = Mock(return_value={})

    assert validate_processor(mock_processor) is True


def test_magic_mock():
    """Test with a MagicMock object."""
    magic_processor = MagicMock()
    # MagicMock doesn't automatically have our specific methods, we need to set them
    magic_processor.process = MagicMock()
    magic_processor.validate_input = MagicMock()
    magic_processor.get_metadata = MagicMock()

    assert validate_processor(magic_processor) is True


def test_partial_mock():
    """Test with Mock missing some methods."""
    partial_mock = Mock()
    partial_mock.process = Mock()
    # Missing validate_input and get_metadata (but Mock auto-creates them)
    assert validate_processor(partial_mock) is True


def test_builtin_types():
    """Test with built-in types that don't have the required methods."""
    assert validate_processor(42) is False
    assert validate_processor("string") is False
    assert validate_processor([1, 2, 3]) is False
    assert validate_processor({"key": "value"}) is False
    assert validate_processor(None) is False


def test_function():
    """Test with a function object."""
    def some_function():
        pass

    assert validate_processor(some_function) is False


def test_lambda():
    """Test with a lambda function."""
    assert validate_processor(lambda x: x) is False


def test_class_itself():
    """Test with the class itself, not an instance."""
    # Classes have the methods as attributes, so @runtime_checkable will return True
    # This is actually correct behavior for runtime_checkable - it checks for attribute existence
    assert validate_processor(ValidProcessor) is True


def test_instance_with_extra_methods():
    """Test with an instance that has extra methods beyond required ones."""
    class ExtendedProcessor(ValidProcessor):
        def extra_method(self):
            pass

    processor = ExtendedProcessor()
    assert validate_processor(processor) is True


def test_protocol_instance():
    """Test with an instance that explicitly implements the Protocol."""
    from typing import Any, Dict

    class ProtocolProcessor:
        def process(self, data: Any) -> Any:
            return data

        def validate_input(self, data: Any) -> bool:
            return True

        def get_metadata(self) -> Dict[str, Any]:
            return {}

    processor = ProtocolProcessor()
    assert validate_processor(processor) is True


def test_methods_returning_wrong_types():
    """Test with methods returning wrong types (should still validate - runtime_checkable only checks existence)."""
    class WrongReturnProcessor:
        def process(self, data: Any) -> str:  # Different return type
            return "wrong"

        def validate_input(self, data: Any) -> str:  # Should return bool but returns str
            return "not a bool"

        def get_metadata(self) -> list:  # Should return dict but returns list
            return []

    processor = WrongReturnProcessor()
    # runtime_checkable only checks method existence, not signatures or return types
    assert validate_processor(processor) is True


def test_inherited_methods():
    """Test with inherited methods."""
    class BaseProcessor:
        def process(self, data: Any) -> Any:
            return data

        def validate_input(self, data: Any) -> bool:
            return True

        def get_metadata(self) -> Dict[str, Any]:
            return {}

    class InheritedProcessor(BaseProcessor):
        pass

    processor = InheritedProcessor()
    assert validate_processor(processor) is True


def test_dynamic_method_addition():
    """Test with methods added dynamically to an object."""
    class EmptyClass:
        pass

    processor = EmptyClass()
    # Add methods dynamically
    processor.process = lambda self, data: data
    processor.validate_input = lambda self, data: True
    processor.get_metadata = lambda self: {}

    # These are callable attributes, so @runtime_checkable should accept them
    assert validate_processor(processor) is True


def test_staticmethod_classmethod():
    """Test with staticmethods and classmethods."""
    class StaticMethodProcessor:
        @staticmethod
        def process(data: Any) -> Any:
            return data

        @staticmethod
        def validate_input(data: Any) -> bool:
            return True

        @staticmethod
        def get_metadata() -> Dict[str, Any]:
            return {}

    processor = StaticMethodProcessor()
    # Static methods are still callable attributes
    assert validate_processor(processor) is True

