    data: DataMapping = {
        "single_key": [(10, 42.0)]
    }
    result = process_data_points(data)
    assert result == [42.0]


def test_mixed_empty_and_nonempty_lists():
    """Test with mixture of empty and non-empty lists."""
    data: DataMapping = {
        "empty": [],
        "full": [(1, 1.1), (2, 2.2)],
        "another_empty": [],
        "another_full": [(3, 3.3)]
    }
