    }
    expected = [999999.999, -999999.999, 0.0]
    result = process_data_points(data)
    assert result == expected


def test_float_precision():
    """Test with floating point numbers that have precision considerations."""
    data: DataMapping = {
        "floats": [(1, 0.1 + 0.2), (2, 1.0 / 3.0)]
    }
    # Using pytest.approx for floating point comparison
    result = process_data_points(data)
    assert result[0] == pytest.approx(0.3)
    assert result[1] == pytest.approx(1.0 / 3.0)


