def try_lock_with_timeout(lock: threading.Lock, timeout: float, action: Callable, fallback: Callable) -> Any:
    acquired = lock.acquire(timeout=timeout)
    try:
        if acquired:
            return action()
        else:
            return fallback()
    finally:
        if acquired:
