class TestValidatePluginConformance:
    def test_valid_plugin_with_runtime_protocol(self):
        """Test that a properly conforming plugin returns True."""
        plugin = ConformingPlugin()
        assert validate_plugin_conformance(plugin, SampleProtocol) is True

    def test_non_conforming_plugin_with_runtime_protocol(self):
        """Test that a non-conforming plugin returns False."""
        plugin = NonConformingPlugin()
        assert validate_plugin_conformance(plugin, SampleProtocol) is False

    def test_empty_protocol_with_conforming_plugin(self):
        """Test that any object conforms to an empty protocol."""
        plugin = ConformingPlugin()
        assert validate_plugin_conformance(plugin, EmptyProtocol) is True

    def test_empty_protocol_with_any_object(self):
        """Test that even basic objects conform to an empty protocol."""
        plugin = object()
        assert validate_plugin_conformance(plugin, EmptyProtocol) is True

    def test_non_runtime_protocol_class(self):
        """Test that non-runtime-checkable Protocol classes return False."""
        class NonRuntimeProtocol(Protocol):
            def method(self) -> str:
                ...

        plugin = Mock()
        assert validate_plugin_conformance(plugin, NonRuntimeProtocol) is False

