        plugin = PluginWithStaticMethod()
        assert validate_plugin_conformance(plugin, StaticMethodProtocol) is True

    def test_inherited_conformance(self):
        """Test that inheritance affects protocol conformance."""
        @runtime_checkable
        class BaseProtocol(Protocol):
