from typing import Sequence
from statistics import linear_regression


def fit_linear_model(x_data: Sequence[float], y_data: Sequence[float], *, force_origin: bool = False) -> tuple[float, float]:
    try:
        result = linear_regression(x_data, y_data, proportional=force_origin)
    except TypeError:
        # `proportional` parameter was added in Python 3.11; fall back for 3.10
        if force_origin:
            denominator = sum(x ** 2 for x in x_data)
            slope = sum(x * y for x, y in zip(x_data, y_data)) / denominator
            return (float(slope), 0.0)
        result = linear_regression(x_data, y_data)
    return (result.slope, result.intercept)

