from itertools import pairwise
from typing import List

def max_consecutive_temp_increase(temperatures: List[float]) -> float:
    if len(temperatures) < 2:
        return 0.0

    max_increase = 0.0
    for curr, next_temp in pairwise(temperatures):
        increase = next_temp - curr
        if increase > max_increase:
            max_increase = increase

    return max_increase

import statistics
from typing import List


def compute_equal_probability_groups(data: List[float], groups: int = 4, method: str = 'exclusive') -> List[float]:
    if groups < 1:
        raise ValueError("Number of groups must be at least 1")
    if not data:
        return []
    if len(data) == 1:
        return [float(data[0])] * (groups - 1)

    return statistics.quantiles(data, n=groups, method=method)

