def map_packages_to_distributions(package_names: List[str]) -> Dict[str, List[str]]:
    all_mappings = importlib.metadata.packages_distributions()

    result = {}
    for package in package_names:
        distributions = all_mappings.get(package, [])
        if distributions:
            result[package] = distributions.copy()

