def test_basic_exception():
    """Test basic exception formatting."""
    try:
        raise ValueError("Test error message")
    except ValueError as e:
        result = format_exception_report(e)
        assert "ValueError" in result
        assert "Test error message" in result
        assert "test_basic_exception" in result  # Should contain function name

def test_exception_with_limit():
    """Test exception formatting with limit parameter."""
    try:
        raise RuntimeError("Limited traceback")
    except RuntimeError as e:
        # Test with small limit
        result = format_exception_report(e, limit=1)
        lines = result.strip().split('\n')
        # Should have limited number of traceback entries
        assert len([l for l in lines if l.startswith('  File')]) <= 1

        # Test with no limit (default)
        result_no_limit = format_exception_report(e, limit=None)
        assert "RuntimeError" in result_no_limit

def test_exception_without_chain():
    """Test exception formatting without chaining."""
    try:
        try:
            raise ValueError("Inner error")
        except ValueError as inner:
            # Create a chain by raising from inner (not from None)
            raise TypeError("Outer error") from inner
    except TypeError as e:
        result_with_chain = format_exception_report(e, chain=True)
        result_without_chain = format_exception_report(e, chain=False)

        # The version without chain should be shorter (no "During handling" or "The above exception")
        assert len(result_without_chain) < len(result_with_chain)
        # Check that chain-related text is not in the result without chain
        assert "During handling" not in result_without_chain
        assert "The above exception" not in result_without_chain

