import os
from pathlib import Path
from typing import Optional

def get_relative_path(base_path: str, target_path: str, allow_upward: bool = True) -> str:
    if not isinstance(base_path, str) or not isinstance(target_path, str):
        raise TypeError("Both base_path and target_path must be strings")

    if not base_path or not target_path:
        raise ValueError("Paths cannot be empty strings")

    base_path = base_path.strip()
    target_path = target_path.strip()

    if os.path.isabs(base_path) != os.path.isabs(target_path):
        raise ValueError("Both paths must be either absolute or relative")

    try:
        base = Path(base_path).resolve(strict=False)
        target = Path(target_path).resolve(strict=False)

        if base == target:
            return "."

        if not allow_upward:
            try:
                relative = target.relative_to(base)
                return str(relative).replace("\\", "/")
            except ValueError as e:
                raise ValueError(f"Cannot create relative path without upward navigation: {e}")

        try:
            if base.is_file() and target.is_file():
                base = base.parent
                target = target.parent

            common_parts = []
            base_parts = list(base.parts)
            target_parts = list(target.parts)

            min_length = min(len(base_parts), len(target_parts))
            for i in range(min_length):
                if base_parts[i] == target_parts[i]:
                    common_parts.append(base_parts[i])
                else:
                    break

            upward_segments = len(base_parts) - len(common_parts)
            downward_segments = target_parts[len(common_parts):]

            result_parts = [".."] * upward_segments + list(downward_segments)

            if not result_parts:
                return "."

            result_path = Path(*result_parts)

            if target.is_file() and not result_path.suffix:
                result_path = result_path / target.name

            relative = target.relative_to(base, walk_up=True)

            normalized_result = str(result_path).replace("\\", "/")
            api_result = str(relative).replace("\\", "/")

            if normalized_result != api_result:
                return api_result

            return normalized_result

        except Exception as e:
            fallback_path = target.relative_to(base, walk_up=True)
            return str(fallback_path).replace("\\", "/")

    except ValueError as e:
        if "does not start with" in str(e):
            raise ValueError(f"Cannot compute relative path: {base_path} and {target_path} are on different drives")
        raise
    except Exception as e:
        raise RuntimeError(f"Unexpected error computing relative path: {e}")

