from dataclasses import dataclass, field, asdict
from typing import Any, Optional, Dict, ClassVar
import logging

logger = logging.getLogger(__name__)

@dataclass
class PipelineConfig:
    name: str
    version: str
    concurrency: int = field(kw_only=True, default=1)
    buffer_size: int = field(kw_only=True, default=1024)
    logging_level: str = field(kw_only=True, default="INFO")
    _required_fields: ClassVar[set] = {"name", "version"}
    _optional_defaults: ClassVar[dict] = {
        "concurrency": 1,
        "buffer_size": 1024,
        "logging_level": "INFO"
    }

    def __post_init__(self):
        if self.concurrency < 1:
            raise ValueError("concurrency must be positive integer")
        if self.buffer_size < 64:
            raise ValueError("buffer_size must be at least 64 bytes")
        valid_levels = {"DEBUG", "INFO", "WARNING", "ERROR", "CRITICAL"}
        if self.logging_level not in valid_levels:
            raise ValueError(f"logging_level must be one of {valid_levels}")

def create_pipeline_config(config_data: dict, strict_validation: bool = True) -> Any:
    if not isinstance(config_data, dict):
        raise TypeError("config_data must be a dictionary")

    missing_fields = PipelineConfig._required_fields - set(config_data.keys())
    if missing_fields:
        raise ValueError(f"Missing required fields: {missing_fields}")

    processed_config = {}
    for field_name in PipelineConfig._required_fields:
        value = config_data.get(field_name)
        if not isinstance(value, str):
            raise TypeError(f"{field_name} must be a string, got {type(value)}")
        processed_config[field_name] = value

    for opt_field, default_val in PipelineConfig._optional_defaults.items():
        if opt_field in config_data:
            if strict_validation and not isinstance(config_data[opt_field], type(default_val)):
                raise TypeError(f"{opt_field} must be {type(default_val).__name__}")
            processed_config[opt_field] = config_data[opt_field]
        else:
            processed_config[opt_field] = default_val

    try:
        config = PipelineConfig(
            name=processed_config["name"],
            version=processed_config["version"],
            concurrency=processed_config["concurrency"],
            buffer_size=processed_config["buffer_size"],
            logging_level=processed_config["logging_level"]
        )
        logger.info(f"Created pipeline config: {config.name} v{config.version}")
        return asdict(config)
    except Exception as e:
        logger.error(f"Failed to create pipeline config: {e}")
        raise

