import pandas as pd
import numpy as np
from typing import Optional, List
import logging

logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def prepare_financial_export(df: pd.DataFrame, include_timestamp: bool = True, columns_to_export: Optional[List[str]] = None) -> dict:
    if not isinstance(df, pd.DataFrame):
        raise ValueError("Input must be a pandas DataFrame")

    if len(df) == 0:
        raise ValueError("DataFrame is empty")

    if columns_to_export is None:
        columns_to_export = df.columns.tolist()
    else:
        missing_cols = [col for col in columns_to_export if col not in df.columns]
        if missing_cols:
            raise ValueError(f"Columns not found in DataFrame: {missing_cols}")

    numeric_cols = df[columns_to_export].select_dtypes(include=[np.number]).columns
    if len(numeric_cols) != len(columns_to_export):
        non_numeric = [col for col in columns_to_export if col not in numeric_cols]
        raise ValueError(f"Non-numeric columns found: {non_numeric}")

    if df[columns_to_export].isna().any().any():
        raise ValueError("Selected columns contain NaN values")

    if include_timestamp and df.index.name is None:
        df = df.copy()
        df.index.name = 'timestamp'

    try:
        result = df[columns_to_export].to_dict(
            orient='tight',
            index=include_timestamp
        )

        if include_timestamp and 'index' in result:
            result['index'] = [ts.isoformat() if hasattr(ts, 'isoformat') else str(ts) 
                             for ts in result['index']]

        logger.info(f"Exported data shape: {len(df)} rows, {len(columns_to_export)} columns")
        return result

    except Exception as e:
        logger.error(f"Failed to export data: {str(e)}")
        raise ValueError(f"Data export failed: {str(e)}")

