import asyncio
from typing import Any, AsyncIterator, List


async def process_concurrent_tasks(
    tasks: List[asyncio.Task], timeout: float | None = None
) -> AsyncIterator[Any]:
    pending = set(tasks)

    try:
        for coro in asyncio.as_completed(pending, timeout=timeout):
            result = await coro
            yield result
    except asyncio.TimeoutError:
        for task in pending:
            if not task.done():
                task.cancel()
        raise

