import functools

def preserve_metadata(wrapped, excluded_attrs=None, extra_wrapper_attrs=None):
    def decorator(wrapper):
        assigned = functools.WRAPPER_ASSIGNMENTS
        if excluded_attrs:
            assigned = tuple(attr for attr in assigned if attr not in excluded_attrs)

        updated = functools.WRAPPER_UPDATES
        if extra_wrapper_attrs:
            updated = updated + tuple(extra_wrapper_attrs)

        return functools.wraps(wrapped, assigned=assigned, updated=updated)(wrapper)
    return decorator

