import unittest
from typing import Any, Callable, Optional

def assert_exception_raised(
    callable_obj: Callable[[], Any], 
    exception_type: type, 
    message_substring: Optional[str] = None
) -> None:
    context = unittest.case._AssertRaisesContext(exception_type, None)

    try:
        callable_obj()
        context.handle("assert_exception_raised", (), {})
    except exception_type as exc:
        if message_substring is not None:
            if message_substring not in str(exc):
                raise AssertionError(
                    f"Substring '{message_substring}' not found in exception message: '{exc}'"
                )
        return

    raise AssertionError(f"{exception_type.__name__} not raised")

