def test_assert_exception_raised_with_inherited_exception():
    """Test that function works with exception inheritance."""
    class SpecificError(ValueError):
        pass

    def raise_specific():
        raise SpecificError("Specific error message")

    # Should pass with exact exception type
    assert_exception_raised(raise_specific, SpecificError)

    # The function checks for exact type, not isinstance, so it should fail
    # when expecting base class but getting derived class
    # Actually, looking at the implementation, it seems to catch the exception
    # and then check if it's the right type. Since SpecificError is caught
    # as exception_type (which would be ValueError in this case), and the
    # actual exception is SpecificError, the isinstance check in unittest
    # would pass. So the test needs to be updated.
    # Let's test what actually happens:
    try:
        assert_exception_raised(raise_specific, ValueError)
        # If we get here, it means the function accepted ValueError as a match
