import pytest
from typing import Dict, List
from solution import parse_query_string


class TestParseQueryString:
    """Test suite for parse_query_string function."""

    def test_basic_query_string(self) -> None:
        """Test basic query string with single values."""
        result = parse_query_string("name=John&age=30&city=NYC")
        expected = {"name": ["John"], "age": ["30"], "city": ["NYC"]}
        assert result == expected

    def test_multiple_values_same_key(self) -> None:
        """Test query string with multiple values for the same key."""
        result = parse_query_string("color=red&color=blue&color=green")
        expected = {"color": ["red", "blue", "green"]}
        assert result == expected

    def test_empty_query_string(self) -> None:
        """Test empty query string."""
        result = parse_query_string("")
        expected: Dict[str, List[str]] = {}
        assert result == expected

    def test_key_without_value(self) -> None:
        """Test keys without values (keep_blank_values=True)."""
        result = parse_query_string("flag=&empty&value=test")
        expected = {"flag": [""], "empty": [""], "value": ["test"]}
        assert result == expected

    def test_url_encoded_values(self) -> None:
        """Test URL-encoded special characters."""
        result = parse_query_string("email=user%40example.com&query=hello%20world%21")
        expected = {"email": ["user@example.com"], "query": ["hello world!"]}
        assert result == expected

    def test_plus_sign_decoding(self) -> None:
        """Test that plus signs are decoded as spaces."""
        result = parse_query_string("search=python+programming&title=test+case")
        expected = {"search": ["python programming"], "title": ["test case"]}
        assert result == expected

    def test_semicolon_separator(self) -> None:
        """Test semicolon as alternative separator."""
        # parse_qs doesn't treat semicolons as separators by default
        result = parse_query_string("name=John;age=30;city=NYC")
        # The entire string after "name=" is treated as the value
        expected = {"name": ["John;age=30;city=NYC"]}
        assert result == expected

    def test_mixed_separators(self) -> None:
        """Test mixed ampersand and semicolon separators."""
        # parse_qs only recognizes & as separators
        result = parse_query_string("a=1&b=2;c=3&d=4")
        expected = {"a": ["1"], "b": ["2;c=3"], "d": ["4"]}
        assert result == expected

    def test_equals_in_value(self) -> None:
        """Test equals sign within URL-encoded values."""
        result = parse_query_string("equation=x%3Dy%2Bz&query=a%3D%3Db")
        expected = {"equation": ["x=y+z"], "query": ["a==b"]}
        assert result == expected

    def test_ampersand_in_value(self) -> None:
        """Test ampersand within URL-encoded values."""
        result = parse_query_string("filter=price%3C100%26available%3Dtrue")
        expected = {"filter": ["price<100&available=true"]}
        assert result == expected

    def test_unicode_characters(self) -> None:
        """Test Unicode characters in query string."""
        result = parse_query_string("name=Caf%C3%A9&city=%E6%9D%B1%E4%BA%AC")
        expected = {"name": ["Café"], "city": ["東京"]}
        assert result == expected

    def test_leading_question_mark(self) -> None:
        """Test query string with leading question mark."""
        # parse_qs treats the question mark as part of the first key
        result = parse_query_string("?name=John&age=30")
        expected = {"?name": ["John"], "age": ["30"]}
        assert result == expected

    def test_only_question_mark(self) -> None:
        """Test query string containing only a question mark."""
        result = parse_query_string("?")
        expected = {"?": [""]}
        assert result == expected

    def test_double_equals(self) -> None:
        """Test key with empty name due to double equals."""
        result = parse_query_string("=value&key=test")
        expected = {"": ["value"], "key": ["test"]}
        assert result == expected

    def test_nested_equals(self) -> None:
        """Test multiple equals signs in a parameter."""
        result = parse_query_string("expr=a%3D%3Db%3D%3Dc")
        expected = {"expr": ["a==b==c"]}
        assert result == expected

    def test_percent_encoding_edge_cases(self) -> None:
        """Test edge cases with percent encoding."""
        result = parse_query_string("test=%25%20%26%3D%3F%23")
        # parse_qs decodes %20 to space, %26 to &, %3D to =, %3F to ?, %23 to #
        expected = {"test": ["% &=?#"]}
        assert result == expected

    def test_incomplete_percent_encoding(self) -> None:
        """Test incomplete percent encoding sequences."""
        result = parse_query_string("data=%41%4%20%%")
        # %41 = 'A', %4 is incomplete so stays as '%4', %20 = space, %% = '%'
        expected = {"data": ["A%4 %%"]}
        assert result == expected

    def test_large_number_of_parameters(self) -> None:
        """Test with a large number of parameters."""
        query_parts = [f"key{i}=value{i}" for i in range(100)]
        query_string = "&".join(query_parts)
        result = parse_query_string(query_string)

        assert len(result) == 100
        for i in range(100):
            assert result[f"key{i}"] == [f"value{i}"]

    def test_whitespace_around_separators(self) -> None:
        """Test whitespace around ampersands and semicolons."""
        result = parse_query_string("a=1  &  b=2 ; c=3&d=4")
        # parse_qs treats whitespace as part of keys/values
        expected = {"a": ["1  "], "  b": ["2 ; c=3"], "d": ["4"]}
        assert result == expected

    def test_return_type_annotation(self) -> None:
        """Verify the return type matches the type annotation."""
        result = parse_query_string("test=value")
        assert isinstance(result, dict)
        assert all(isinstance(key, str) for key in result.keys())
        assert all(isinstance(value, list) for value in result.values())
        assert all(isinstance(item, str) for value in result.values() for item in value)

    def test_identical_keys_different_casing(self) -> None:
        """Test that keys with different casing are treated as different."""
        result = parse_query_string("KEY=value1&key=value2&Key=value3")
        expected = {"KEY": ["value1"], "key": ["value2"], "Key": ["value3"]}
        assert result == expected

    @pytest.mark.parametrize("input_str,expected", [
        ("single=value", {"single": ["value"]}),
        ("", {}),
        ("a=1&b=2&c=3", {"a": ["1"], "b": ["2"], "c": ["3"]}),
        ("key=", {"key": [""]}),
        ("=value", {"": ["value"]}),
        ("a=1&a=2&a=3", {"a": ["1", "2", "3"]}),
    ])
    def test_parametrized_cases(self, input_str: str, expected: Dict[str, List[str]]) -> None:
        """Test multiple cases using pytest parametrization."""
        result = parse_query_string(input_str)
        assert result == expected

