import ctypes
from typing import Optional

def decode_wide_string_from_memory(address: int, encoding: str = 'utf-16', size: int = -1) -> str:
    if address == 0:
        raise ValueError("Invalid memory address: 0")

    if size == -1:
        raw_data = ctypes.wstring_at(address)
    else:
        raw_data = ctypes.wstring_at(address, size)

    return raw_data

