import json


async def process_async_stream(source: AsyncIterator[bytes]) -> AsyncIterator[dict]:
    async for chunk in source:
        try:
            data = json.loads(chunk.decode('utf-8'))
            if isinstance(data, dict):
                yield data
        except (json.JSONDecodeError, UnicodeDecodeError):
            continue

import os
import re

# Fallback pattern matching os.path.expandvars behavior for ${VAR} variables
_FALLBACK_VARPROG = re.compile(r'\$\{([^}]*)\}')

def expand_env_vars_in_path(path: str) -> str:
    # Try os.path._varprog (available in Python < 3.13), else use fallback
    try:
        varprog = os.path._varprog
        if varprog is None:
            return path
    except AttributeError:
        varprog = _FALLBACK_VARPROG

    i = 0
    while True:
        match = varprog.search(path, i)
        if not match:
            break

        i, j = match.span(0)
        name = match.group(1)

        if name:
            tail = path[j:]
            value = os.environ.get(name)
            if value is None:
                i = j + 1
            else:
                path = path[:i] + value + tail
                i = i + len(value)
        else:
            i = j + 1

    return path

