import subprocess
import shlex
from typing import Optional

def secure_command_execution(command_parts: list[str], timeout: int = 30) -> tuple[int, str, str]:
    if not command_parts:
        raise ValueError("command_parts must not be empty")

    try:
        process = subprocess.Popen(
            command_parts,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding='utf-8',
            errors='replace'
        )

        try:
            stdout, stderr = process.communicate(timeout=timeout)
        except subprocess.TimeoutExpired:
            process.kill()
            stdout, stderr = process.communicate()
            return (process.returncode or -1, stdout or "", stderr or "")

        return (process.returncode, stdout or "", stderr or "")

    except FileNotFoundError:
        return (127, "", f"Command not found: {command_parts[0]}")
    except PermissionError:
        return (126, "", f"Permission denied: {command_parts[0]}")
    except OSError as e:
        return (125, "", f"OS error: {str(e)}")

