import ctypes
from typing import Type, Any, Dict, Optional
import hashlib
import sys

def create_dynamic_pointer_type(struct_name: str, fields: list[tuple[str, type]]) -> Type:
    """
    Dynamically creates a pointer type for a C struct with comprehensive validation,
    caching, and Python 3.12 optimizations.
    """
    # Input validation with detailed error messages
    if not isinstance(struct_name, str) or not struct_name.isidentifier():
        raise ValueError(f"Invalid struct name '{struct_name}'. Must be a valid Python identifier.")

    if not isinstance(fields, list):
        raise TypeError(f"Fields must be a list, got {type(fields).__name__}")

    if not fields:
        raise ValueError("Fields list cannot be empty")

    # Validate each field tuple
    validated_fields = []
    for i, field in enumerate(fields):
        try:
            if not isinstance(field, tuple) or len(field) != 2:
                raise ValueError(f"Field at index {i} must be a 2-element tuple")

            field_name, field_type = field

            if not isinstance(field_name, str) or not field_name.isidentifier():
                raise ValueError(f"Invalid field name '{field_name}' at index {i}")

            # Validate ctypes compatibility
            if not hasattr(ctypes, field_type.__name__) and not issubclass(field_type, ctypes._SimpleCData):
                raise TypeError(f"Unsupported type {field_type} for field '{field_name}'")

            validated_fields.append((field_name, field_type))

        except (ValueError, TypeError) as e:
            raise type(e)(f"Field validation failed at index {i}: {str(e)}")

    # Create a cache key for memoization
    cache_key = hashlib.md5(
        f"{struct_name}:{str([(n, t.__name__) for n, t in validated_fields])}".encode()
    ).hexdigest()

    # Check cache to avoid redundant type creation
    cache_attr = f"_dynamic_pointer_cache_{cache_key}"
    if hasattr(ctypes, cache_attr):
        cached_type = getattr(ctypes, cache_attr)
        if isinstance(cached_type, type) and issubclass(cached_type, ctypes._Pointer):
            return cached_type

    # Create the base structure with additional metadata
    struct_attrs = {
        '_fields_': validated_fields,
        '_pack_': 8,  # Default alignment for performance
        '__doc__': f"Dynamically generated struct '{struct_name}' with {len(validated_fields)} fields"
    }

    # Add Python 3.12 specific optimizations
    if sys.version_info >= (3, 12):
        struct_attrs['_anonymous_'] = []  # Enable anonymous unions if needed
        struct_attrs['_alignment_'] = max(
            ctypes.alignment(field_type) for _, field_type in validated_fields
        )

    try:
        struct_type = type(struct_name, (ctypes.Structure,), struct_attrs)
    except Exception as e:
        raise RuntimeError(f"Failed to create struct type '{struct_name}': {str(e)}")

    # Create pointer type with validation
    try:
        pointer_type = ctypes.POINTER(struct_type)

        # Verify pointer type creation
        if not issubclass(pointer_type, ctypes._Pointer):
            raise TypeError("Failed to create valid pointer type")

        # Set pointer type with error handling
        ctypes.SetPointerType(struct_type, pointer_type)

        # Additional validation: ensure the pointer type works
        test_instance = struct_type()
        test_pointer = ctypes.pointer(test_instance)

        if not isinstance(test_pointer, pointer_type):
            raise RuntimeError("Pointer type validation failed")

        # Cache the created type for future use
        setattr(ctypes, cache_attr, pointer_type)

        return pointer_type

    except Exception as e:
        # Clean up any partially created types
        if 'struct_type' in locals():
            del struct_type
        raise RuntimeError(f"Failed to create pointer type for '{struct_name}': {str(e)}")

