import pkgutil
import sys
import warnings
from importlib.abc import Loader, MetaPathFinder
from importlib.machinery import BuiltinImporter, FrozenImporter, PathFinder
from typing import Optional, Dict, Any, List, Tuple
from types import ModuleType

def get_module_loader(module_name: str) -> Optional[Loader]:
    """
    Retrieve an appropriate loader for the specified module name with enhanced
    validation, caching, and edge case handling for namespace packages,
    built-in modules, and performance optimization.
    """
    # Comprehensive input validation
    if not isinstance(module_name, str):
        raise TypeError(f"module_name must be a string, got {type(module_name).__name__}")

    if not module_name:
        warnings.warn("Empty module name provided, returning None", UserWarning)
        return None

    # Normalize module name and check for invalid patterns
    normalized_name = module_name.strip()
    if normalized_name != module_name:
        warnings.warn(f"Module name '{module_name}' contains leading/trailing whitespace, normalized to '{normalized_name}'")

    if any(char in normalized_name for char in '<>:"|?*\\'):
        warnings.warn(f"Module name '{normalized_name}' contains potentially invalid characters")

    # Cache for frequently requested modules to improve performance
    _loader_cache: Dict[str, Optional[Loader]] = {}
    if normalized_name in _loader_cache:
        cached_loader = _loader_cache[normalized_name]
        if cached_loader is not None and hasattr(cached_loader, 'is_package'):
            return cached_loader

    # Special handling for built-in and frozen modules
    if normalized_name in sys.builtin_module_names:
        try:
            builtin_loader = BuiltinImporter.find_module(normalized_name)
            if builtin_loader and isinstance(builtin_loader, Loader):
                _loader_cache[normalized_name] = builtin_loader
                return builtin_loader
        except (ImportError, AttributeError) as e:
            warnings.warn(f"Failed to get builtin loader for '{normalized_name}': {e}")

    # Check if module is already loaded and inspect its loader
    loaded_module = sys.modules.get(normalized_name)
    if loaded_module and hasattr(loaded_module, '__loader__'):
        existing_loader = loaded_module.__loader__
        if isinstance(existing_loader, Loader):
            _loader_cache[normalized_name] = existing_loader
            return existing_loader

    # Primary loader retrieval with enhanced error handling
    try:
        loader = pkgutil.get_loader(normalized_name)

        # Additional validation and transformation
        if loader is not None:
            # Check for namespace package indicators
            if hasattr(loader, 'path') and loader.path is None:
                warnings.warn(f"Module '{normalized_name}' appears to be a namespace package")

            # Verify loader compatibility with current Python version
            if sys.version_info >= (3, 12):
                # Python 3.12+ specific optimizations
                if hasattr(loader, '__spec__') and loader.__spec__ is not None:
                    spec = loader.__spec__
                    if spec.loader is not None and isinstance(spec.loader, Loader):
                        _loader_cache[normalized_name] = spec.loader
                        return spec.loader

            # Ensure loader implements required interface
            required_methods = ['load_module', 'create_module', 'exec_module']
            implemented_methods = []

            for method in required_methods:
                if hasattr(loader, method) and callable(getattr(loader, method)):
                    implemented_methods.append(method)

            if len(implemented_methods) >= 2:
                if isinstance(loader, Loader):
                    _loader_cache[normalized_name] = loader
                    return loader
                else:
                    warnings.warn(f"Loader for '{normalized_name}' has methods {implemented_methods} but doesn't inherit from Loader")
            else:
                warnings.warn(f"Loader for '{normalized_name}' missing required methods, only has {implemented_methods}")

        # Fallback: Check all meta path finders
        if loader is None:
            for finder in sys.meta_path:
                if isinstance(finder, MetaPathFinder):
                    try:
                        found_loader = finder.find_module(normalized_name, None)
                        if found_loader and isinstance(found_loader, Loader):
                            _loader_cache[normalized_name] = found_loader
                            return found_loader
                    except Exception as e:
                        warnings.warn(f"Finder {finder.__class__.__name__} failed for '{normalized_name}': {e}")
                        continue

        # Cache negative results to avoid repeated lookups
        _loader_cache[normalized_name] = None
        return None

    except ImportError as e:
        warnings.warn(f"ImportError retrieving loader for '{normalized_name}': {e}")
        return None
    except Exception as e:
        warnings.warn(f"Unexpected error retrieving loader for '{normalized_name}': {e}")
        return None

from sklearn.model_selection import cross_validate
import numpy as np
from numbers import Number
from typing import Dict, List, Union, Optional

def robust_cv_evaluation(estimator, X, y=None, *, scoring=None, cv=5, n_jobs=None, fit_params=None, return_fold_indices=True, error_fill_value=None, metric_filter_threshold=0) -> dict:
    if X is None or len(X) == 0:
        raise ValueError("Input data X cannot be None or empty")
    if scoring is None:
        raise ValueError("At least one scoring metric must be provided")
    if not isinstance(cv, (int, Number)) or cv < 2:
        raise ValueError("cv must be an integer >= 2")

    if error_fill_value is None:
        error_fill_value = np.nan

    try:
        cv_results = cross_validate(
            estimator, X, y, 
            scoring=scoring, 
            cv=cv, 
            n_jobs=n_jobs,
            fit_params=fit_params,
            return_estimator=False,
            return_indices=return_fold_indices,
            error_score='raise'
        )
    except Exception as e:
        raise RuntimeError(f"Cross-validation failed: {str(e)}")

    processed_metrics = {}
    if isinstance(scoring, dict):
        metric_names = list(scoring.keys())
    elif isinstance(scoring, (list, tuple)):
        metric_names = list(scoring)
    else:
        metric_names = [scoring]

    for metric in metric_names:
        test_key = f'test_{metric}'
        if test_key not in cv_results:
            continue

        fold_scores = cv_results[test_key]
        valid_scores = []
        for i, score in enumerate(fold_scores):
            if np.isnan(score) or score is None:
                if metric_filter_threshold > 0:
                    fold_scores[i] = error_fill_value
                else:
                    valid_scores.append(error_fill_value)
            else:
                valid_scores.append(score)

        if len(valid_scores) == 0:
            overall_score = error_fill_value
        else:
            overall_score = np.nanmean(valid_scores) if metric_filter_threshold == 0 else np.mean(valid_scores)

        processed_metrics[metric] = {
            'overall_score': float(overall_score),
            'fold_scores': [float(s) for s in fold_scores],
            'valid_fold_count': len(valid_scores)
        }

    report = {
        'metrics': processed_metrics,
        'cv_parameters': {
            'n_splits': cv,
            'scoring_metrics': metric_names
        }
    }

    if return_fold_indices and 'indices' in cv_results:
        report['fold_indices'] = cv_results['indices']

    return report

