def process_async_handlers(handler_list: List[Tuple[Optional[Callable], Dict[str, Any]]]) -> Dict[int, List[Dict[str, Any]]]:
    if not isinstance(handler_list, list):
        raise TypeError("handler_list must be a list")

    valid_handlers_by_priority = {}

    for handler, metadata in handler_list:
        if handler is None:
            logger.warning("Encountered None handler, skipping")
            continue

        if not callable(handler):
            logger.warning(f"Handler {handler} is not callable, skipping")
            continue

        try:
            if not asyncio.iscoroutinefunction(handler):
                logger.warning(f"Handler {handler.__name__ if hasattr(handler, '__name__') else handler} is not a coroutine function")
                continue
        except Exception as e:
            logger.warning(f"Error checking coroutine status for {handler}: {e}")
            continue

        priority = metadata.get('priority', 0)
        if not isinstance(priority, int):
            logger.warning(f"Invalid priority type for handler {handler}, using default priority 0")
            priority = 0

        handler_info = {
            'handler': handler,
            'metadata': metadata.copy(),
            'handler_name': handler.__name__ if hasattr(handler, '__name__') else str(handler)
        }

        if priority not in valid_handlers_by_priority:
            valid_handlers_by_priority[priority] = []

        valid_handlers_by_priority[priority].append(handler_info)

    for priority in valid_handlers_by_priority:
        valid_handlers_by_priority[priority].sort(
            key=lambda x: x['metadata'].get('order', 0)
        )

    return valid_handlers_by_priority

