import os
import sysconfig
import shutil
from pathlib import Path
from typing import Set

def process_makefile_templates(
    template_dir: str,
    output_dir: str,
    variables: dict[str, str],
    dry_run: bool = False
) -> dict[str, list[str]]:
    template_path = Path(template_dir)
    output_path = Path(output_dir)

    if not template_path.exists() or not template_path.is_dir():
        raise ValueError(f"Template directory does not exist: {template_dir}")

    if not dry_run:
        output_path.mkdir(parents=True, exist_ok=True)

    results = {"processed": [], "skipped": [], "errors": []}
    template_files = [f for f in template_path.iterdir() if f.is_file() and f.suffix == ".in"]

    for template_file in template_files:
        try:
            with open(template_file, 'r', encoding='utf-8') as f:
                content = f.read()

            expanded_content = sysconfig.expand_makefile_vars(content, variables)

            unresolved_vars = set()
            for var in variables:
                if f"$({var})" in expanded_content:
                    unresolved_vars.add(var)

            if unresolved_vars:
                results["errors"].append(f"{template_file.name}: Unresolved variables: {unresolved_vars}")
                continue

            output_file = output_path / template_file.stem

            if dry_run:
                results["processed"].append(f"Would process: {template_file.name} -> {output_file.name}")
            else:
                with open(output_file, 'w', encoding='utf-8') as f:
                    f.write(expanded_content)
                shutil.copymode(template_file, output_file)
                results["processed"].append(f"Processed: {template_file.name}")

        except Exception as e:
            results["errors"].append(f"{template_file.name}: {str(e)}")

    if results["errors"] and not dry_run:
        raise RuntimeError(f"Template processing failed with errors: {results['errors']}")

    return results

