logging.basicConfig(level=logging.WARNING)
logger = logging.getLogger(__name__)

def register_plugins_from_config(configs: List[Dict[str, Any]], existing_names: Set[str] = None) -> Dict[str, types.ModuleType]:
    if existing_names is None:
        existing_names = set()

    if not isinstance(configs, list):
        logger.warning("Configs must be a list, got %s", type(configs).__name__)
        return {}

    registered = {}
    seen_names = set(existing_names)

    for idx, config in enumerate(configs):
        if not isinstance(config, dict):
            logger.warning("Config entry %d is not a dictionary, skipping", idx)
            continue

        name = config.get('name')
        metadata = config.get('metadata', {})

        if not isinstance(name, str):
            logger.warning("Plugin name at index %d must be a string, skipping", idx)
            continue

        if not name.isidentifier():
            logger.warning("Plugin name '%s' is not a valid Python identifier", name)
            continue

        if name in seen_names:
            logger.warning("Plugin name '%s' already registered, skipping duplicate", name)
            continue

        try:
            module = types.ModuleType(name)
            module._plugin_metadata = metadata
            module.__file__ = f"<plugin:{name}>"

            if isinstance(metadata, dict):
                for key, value in metadata.items():
                    if isinstance(key, str) and key.isidentifier():
                        setattr(module, key, value)

            registered[name] = module
            seen_names.add(name)

        except Exception as e:
            logger.warning("Failed to create module for plugin '%s': %s", name, str(e))
            continue

    return registered

