from pydoc import ErrorDuringImport

def audit_module_imports(module_names: list[str]) -> tuple[dict[str, dict[str, Any]], list[Any]]:
    if not isinstance(module_names, list):
        raise TypeError("module_names must be a list")

    successful_imports: Dict[str, Dict[str, Any]] = {}
    import_errors: List[Any] = []

    for module_name in module_names:
        if not isinstance(module_name, str):
            continue

        if '-' in module_name:
            continue

        try:
            module = importlib.import_module(module_name)
            metadata: Dict[str, Any] = {
                'name': module.__name__,
                'file': getattr(module, '__file__', None),
                'doc': getattr(module, '__doc__', None)
            }

            if hasattr(module, '__version__'):
                metadata['version'] = module.__version__
            elif hasattr(module, 'VERSION'):
                metadata['version'] = module.VERSION
            elif hasattr(module, 'version'):
                metadata['version'] = module.version

            successful_imports[module_name] = metadata

        except ErrorDuringImport as e:
            error_info = {
                'module': module_name,
                'error_type': type(e).__name__,
                'error_msg': str(e),
                'traceback': getattr(e, '__traceback__', None)
            }
            import_errors.append(error_info)
        except Exception as e:
            if isinstance(e, (SyntaxError, ImportError)):
                error_info = {
                    'module': module_name,
                    'error_type': type(e).__name__,
                    'error_msg': str(e),
                    'context': getattr(e, 'msg', None)
                }
                import_errors.append(error_info)

    return successful_imports, import_errors

