def process_large_xml_transactions(file_path: str, validator: Callable[[ET.Element], bool]) -> List[Dict[str, Any]]:
    transactions = []
    transaction_data = {}
    current_element = None

    for event, elem in ET.iterparse(file_path, events=('start', 'end')):
        if event == 'start':
            current_element = elem.tag
        elif event == 'end':
            if elem.tag == 'transaction':
                if validator(elem):
                    transactions.append(transaction_data.copy())
                transaction_data.clear()
                elem.clear()
            elif current_element and elem.text and elem.text.strip():
                transaction_data[elem.tag] = elem.text.strip()

    return transactions

