import tempfile
import warnings


def create_temp_filepath(suffix: str = '', prefix: str = 'tmp', directory: str = None) -> str:
    with warnings.catch_warnings():
        warnings.filterwarnings("error", category=RuntimeWarning)
        try:
            return tempfile.mktemp(suffix=suffix, prefix=prefix, dir=directory)
        except RuntimeWarning:
            warnings.filterwarnings("ignore", category=RuntimeWarning)
            return tempfile.mktemp(suffix=suffix, prefix=prefix, dir=directory)

