async def stream_until_eof(reader: asyncio.StreamReader, chunk_size: int = 4096) -> bytes:
    """Read data from a stream until EOF is reached."""
    if chunk_size <= 0:
        raise ValueError("chunk_size must be positive")

    chunks: list[bytes] = []

    while True:
        try:
            chunk = await reader.read(chunk_size)
            if not chunk:
                break
            chunks.append(chunk)
        except RuntimeError as e:
            if "EOF" in str(e) or "empty" in str(e).lower():
                break
            raise

    return b''.join(chunks)

