def validate_adapter_extra_propagation(logger: logging.Logger, extra_context: Dict[str, Any]) -> bool:
    class TestAdapter(logging.LoggerAdapter):
        def process(self, msg, kwargs):
            kwargs["extra"] = self.extra
            return msg, kwargs

    adapter = TestAdapter(logger, extra_context)

    class TestHandler(logging.Handler):
        def __init__(self):
            super().__init__()
            self.last_record = None

        def emit(self, record):
            self.last_record = record

    handler = TestHandler()
    logger.addHandler(handler)
    logger.setLevel(logging.DEBUG)

    try:
        adapter.debug("Test message")

        if handler.last_record is None:
            return False

        for key, expected_value in extra_context.items():
            if not hasattr(handler.last_record, key):
                return False
            if getattr(handler.last_record, key) != expected_value:
                return False

        return True
    finally:
        logger.removeHandler(handler)

